INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1150064100', 260, 'Banghwa 3-dong', '방화3동', 'Gangseo-gu', '강서구', 'M193.9,411.81 L184.5,417.98 L176.16,427.38 L173.15,432.64 L171.12,433.39 L168.34,435.65 L162.7,442.64 L161.42,449.34 L161.95,453.93 L164.9,456.55 L148.95,456.08 L149.11,450.18 L146.9,449.97 L126.32,449.04 L123.3,450.53 L122.69,452.69 L116.4,453.52 L112.97,453.3 L113.15,451.82 L116.38,442.42 L118.71,439.71 L119.61,433.92 L117.51,433.7 L119.58,429.81 L120.29,427.68 L120.07,424.9 L124.28,423.84 L125.8,421.15 L127.81,419.03 L132.4,419.63 L136.23,421.74 L138.94,418.65 L141.12,419.93 L142.62,423.17 L144.05,417.83 L144.8,412.94 L144.73,411.21 L142.25,409.93 L143.67,407.98 L142.7,407.15 L155.4,383.38 L172.32,398.58 L178.86,403.69 L193.9,411.81 Z', 'held', '["free-city"]', 'The creative maintenance team at the Gangseo Technical High School workspace takes orders for household tools and vehicle parts together, but skilled labor is limited.', '강서공업고등학교 작업 공간의 창작 정비조는 생활 공구와 차량용 부품 주문을 함께 받지만 숙련 인력은 한정돼 있다.', 'The residents of Banghwa 3-dong negotiate the cost of their next choice: securing workbenches for household tools.', '방화3동 주민들은 다음 선택의 비용을 협의한다: 생활 공구용 작업대를 확보한다.', 1, 2552797.929997004, 2486.330753177729);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153051000', 261, 'Sindorim-dong', '신도림동', 'Guro-gu', '구로구', 'M372.67,692.42 L368.97,694.82 L362,694.65 L360.94,693.34 L357.91,692.29 L344.84,701.81 L337.52,708.01 L334.82,708.62 L334.12,708.37 L332.7,707.13 L329.58,703.74 L324.65,703.73 L320.68,701.64 L310.58,690.68 L324.99,670.04 L327.96,661.1 L334.42,664.59 L356.96,678.16 L359.95,680.89 L362.99,686.18 L366.48,687.67 L372.67,692.42 Z', 'held', '["free-city"]', 'The creative operations team at the Sindorim transfer space must decide whether to repair broken carrying equipment in the passage or move it to a space set aside out of the way.', '신도림 환승 공간의 창작 운영조는 고장 난 운반 장비를 통로에서 수리할지 비켜 둔 공간으로 옮길지 결정해야 한다.', 'The residents of Sindorim-dong negotiate the cost of their next choice: moving the maintenance area out of the passage.', '신도림동 주민들은 다음 선택의 비용을 협의한다: 정비 구획을 통로 밖으로 옮긴다.', 3, 1375464.764538088, 7790.384949336358);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153052000', 262, 'Guro 1-dong', '구로1동', 'Guro-gu', '구로구', 'M330.63,772 L323.3,770.79 L318.24,773.23 L313.65,774 L314.85,770.04 L315.28,762.67 L308.1,761.65 L300.34,750.39 L299.22,748.22 L299.13,745.04 L297.15,738.91 L295.42,738.89 L294.67,731.83 L295.76,734.07 L303.78,732.25 L309.87,728.59 L324.33,722.14 L329.54,721.19 L328.22,725.61 L327.78,731.14 L328.91,748.43 L328.35,752.71 L328.82,762.85 L329.16,766.84 L330.63,772 Z', 'held', '["free-city"]', 'Guro 1-dong has a large open basin by the station, now frozen over. Residents keep the paths around it clear and carry food along the safe walking line, with one free-city station counting arrivals. The open ice is a place where outside machines can approach, so no one lingers there after dark.', '구로1동에는 역 옆에 큰 빈 유수지가 있고 지금은 얼어 있다. 주민들은 그 둘레 길을 치우고 안전한 통행선으로 식량을 나르며, 자유도시의 역 한 곳이 도착한 사람을 센다. 트인 얼음판은 바깥 기계가 다가올 수 있는 곳이라 해가 진 뒤에는 아무도 머물지 않는다.', 'On opening day, Guro 1-dong residents inspect the inlet and the detour footpath together and put out markers on the thin ice.', '개막일 구로1동 주민들은 유입구와 우회 보행로를 함께 점검하고 얇은 얼음 위에 표지를 세운다.', 1, 1082490.8651219665, 5546.651887287284);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153053000', 263, 'Guro 2-dong', '구로2동', 'Guro-gu', '구로구', 'M328.63,710.63 L339.18,722.8 L340.48,723.9 L342.51,724.97 L349.72,731.8 L358.76,746.13 L351.74,757.89 L344.67,756.71 L340.86,755.53 L340.52,755.7 L341.56,761.42 L342.58,765.14 L346.08,775.65 L337,769.76 L329.21,767.04 L328.35,752.71 L328.91,748.43 L327.77,729.67 L328.22,725.61 L329.54,721.19 L324.33,722.14 L309.87,728.59 L303.78,732.25 L295.76,734.07 L294.67,731.83 L304.15,701.07 L310.58,690.68 L320.68,701.64 L324.65,703.73 L329.58,703.74 L332.7,707.13 L328.63,710.63 Z', 'held', '["free-city"]', 'The creative medical team in the building marked as Korea University Guro Hospital wants to fix the washing equipment in the treatment space, but nearby households are also waiting for the same parts.', '고려대학교구로병원으로 표시된 건물의 창작 의무조는 처치 공간의 세척 설비를 고치려 하지만 주변 가구도 같은 부품을 기다린다.', 'The residents of Guro 2-dong negotiate the cost of their next choice: repairing the medical washing equipment first.', '구로2동 주민들은 다음 선택의 비용을 협의한다: 의무 세척 설비를 먼저 수리한다.', 0, 1808608.8570230417, 3580.5420142966263);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153054000', 264, 'Guro 3-dong', '구로3동', 'Guro-gu', '구로구', 'M384.44,792.6 L382.93,797.6 L374.93,798.99 L374.6,798.15 L369.85,793.02 L367.25,792.81 L363.35,791.37 L361.17,781.51 L361.83,780.4 L350.25,776.2 L346.53,775.68 L352.73,766.84 L362.52,758.63 L373.04,750.45 L379.14,766.46 L382.09,769.6 L387.38,773.46 L394,775.87 L395.33,775.96 L384.44,792.6 Z', 'held', '["free-city"]', 'The work crews around the Guro Digital Complex want to change the handover schedule so that commuting workers and parts boxes are not received at the same time.', '구로디지털단지 주변 작업반은 출퇴근 인원과 부품 상자를 같은 시간에 받지 않도록 인계표를 바꾸려 한다.', 'The residents of Guro 3-dong negotiate the cost of their next choice: securing worker transit times first.', '구로3동 주민들은 다음 선택의 비용을 협의한다: 작업자 통과 시간을 먼저 확보한다.', 2, 1042354.39201667, 6514.291158559638);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153055000', 265, 'Guro 4-dong', '구로4동', 'Guro-gu', '구로구', 'M373.04,750.45 L362.52,758.63 L352.73,766.84 L346.53,775.68 L346.08,775.65 L342.58,765.14 L341.56,761.42 L340.52,755.7 L340.86,755.53 L344.67,756.71 L351.74,757.89 L358.76,746.13 L354.25,738.62 L367.8,729.93 L370.65,742.19 L373.04,750.45 Z', 'held', '["free-city"]', 'The Dorimcheon in Guro 4-dong is frozen, and residents share the same people between clearing debris on the bank and repairing rooms inside. There is no station of its own, so goods pass through the check at a neighboring dong. The stream edge is not a safe way across, and outside machines can come along the icy bank.', '구로4동의 도림천은 얼어 있고, 주민들은 천변 잔해를 치우는 일과 실내 보수에 같은 사람들을 나눠 쓴다. 자체 역이 없어 짐은 이웃 동의 검사를 거친다. 천변은 안전하게 건널 길이 아니며, 얼어붙은 둑을 따라 바깥 기계가 다가올 수 있다.', 'On opening day, Guro 4-dong residents clear the debris that blocks the alleys behind the houses first.', '개막일 구로4동 주민들은 집 뒤 골목을 막은 잔해부터 먼저 치운다.', 0, 516118.77206599485, 10193.58388949913);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153056000', 266, 'Guro 5-dong', '구로5동', 'Guro-gu', '구로구', 'M368.41,705.85 L367.58,710.45 L367.27,716.29 L367.8,729.93 L354.25,738.62 L349.72,731.8 L342.51,724.97 L340.48,723.9 L339.18,722.8 L328.63,710.63 L332.7,707.13 L334.12,708.37 L334.82,708.62 L337.52,708.01 L344.84,701.81 L357.91,692.29 L360.94,693.34 L362,694.65 L368.97,694.82 L368.41,705.85 Z', 'held', '["free-city"]', 'The Guro Station handover team wants to make the pickup order and owners public so that no particular work crew takes supplies from outside first.', '구로역 인계조는 외부에서 온 물자를 특정 작업반이 먼저 가져가지 않도록 수령 순서와 소유자를 공개하려 한다.', 'The residents of Guro 5-dong negotiate the cost of their next choice: checking reserved orders and recipients together.', '구로5동 주민들은 다음 선택의 비용을 협의한다: 예약 주문과 수령자를 함께 확인한다.', 1, 1022494.7453295469, 8342.83016021823);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153059500', 267, 'Garibong-dong', '가리봉동', 'Guro-gu', '구로구', 'M345.76,775.63 L350.25,776.2 L361.83,780.4 L361.17,781.51 L363.35,791.37 L367.25,792.81 L369.85,793.02 L374.6,798.15 L374.93,798.99 L374.06,799.33 L371.03,799.11 L358.43,796.34 L355.89,795.6 L353.06,794 L350.48,791.49 L344.35,783.35 L335.23,775.42 L330.63,772 L329.21,767.04 L337,769.76 L345.76,775.63 Z', 'held', '["free-city"]', 'The apprentices around the site recorded as Seoul Digital National Industrial Complex, Zone 1, want to change the practice of taking on long hours of odd jobs in exchange for receiving training.', '서울디지털국가산업단지 1단지로 기록된 부지 주변의 도제들은 훈련을 받는 대신 장시간 잡무를 맡는 관행을 바꾸려 한다.', 'The residents of Garibong-dong negotiate the cost of their next choice: publicly scheduling apprentice practice hours.', '가리봉동 주민들은 다음 선택의 비용을 협의한다: 도제 실습 시간을 공개 예약한다.', 0, 407986.25634201895, 6523.013848214056);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153072000', 268, 'Gocheok 1-dong', '고척1동', 'Guro-gu', '구로구', 'M294.67,731.83 L295.11,737.36 L283.59,742.76 L283.39,739.93 L281.98,735.21 L280.53,732.64 L278.98,733.33 L273.08,732.42 L262.03,729.85 L258.95,723.5 L260.44,712.95 L263.6,713.23 L264.38,709.66 L262.13,707.39 L262.28,706.88 L264.15,706.04 L275.73,703.97 L279.77,699.55 L280.94,702.26 L281.96,703.28 L299.49,701.85 L304.15,701.07 L294.67,731.83 Z', 'held', '["free-city"]', 'The residents who use Gocheok Elementary School as a communal timber store want to keep the wet timber separate from the dry materials.', '고척초등학교를 공동 목재 보관소로 쓰는 주민들은 젖은 부재를 건조한 재료와 분리하려 한다.', 'The residents of Gocheok 1-dong negotiate the cost of their next choice: creating a drying zone for wet timber.', '고척1동 주민들은 다음 선택의 비용을 협의한다: 젖은 부재의 건조 구획을 만든다.', 0, 1132062.6447691275, 6952.08877032158);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153073000', 269, 'Gocheok 2-dong', '고척2동', 'Guro-gu', '구로구', 'M266.68,685.27 L272.19,697.03 L278.94,697.08 L279.77,699.55 L275.73,703.97 L264.15,706.04 L262.28,706.88 L262.13,707.39 L264.38,709.66 L263.6,713.23 L260.44,712.95 L256.38,711.6 L251.66,722.48 L250.89,722.83 L243.02,716.14 L238.66,710.46 L235.6,703.53 L229.76,692.48 L235.19,689.2 L251.64,682.89 L254.85,683.89 L260.74,686.94 L266.68,685.27 Z', 'held', '["free-city"]', 'The merchants of Gocheok Neighborhood Market want to manage the reusable boxes jointly, but the boundary between personal goods and shared boxes is unclear.', '고척근린시장 상인들은 반복 사용할 상자를 공동으로 관리하려 하지만 개인 물품과 공용 상자의 경계가 모호하다.', 'The residents of Gocheok 2-dong negotiate the cost of their next choice: creating a lending sheet for shared boxes.', '고척2동 주민들은 다음 선택의 비용을 협의한다: 공용 상자 대여표를 만든다.', 0, 996398.1042593844, 7431.668093652193);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153074000', 270, 'Gaebong 1-dong', '개봉1동', 'Guro-gu', '구로구', 'M260.44,712.95 L258.95,723.5 L262.03,729.85 L273.08,732.42 L278.98,733.33 L280.53,732.64 L281.98,735.21 L283.39,739.93 L283.59,742.76 L280.73,742.9 L269.55,741.96 L267.62,741.47 L265.45,739.62 L258.73,737.49 L252.32,735.9 L245.14,736.3 L242.84,733.03 L238.34,729.29 L226.26,721.89 L217.51,720.22 L210.79,719.86 L209.69,720.16 L209.78,715.36 L211.54,710.24 L216.25,706.34 L221.18,703.16 L227.55,697.62 L229.76,692.48 L235.6,703.53 L238.66,710.46 L243.02,716.14 L250.09,722.19 L250.89,722.83 L251.66,722.48 L256.38,711.6 L260.44,712.95 Z', 'held', '["free-city"]', 'The guide team around Gaebong Station sets an allocation order between the lighting needed for night passage and the power for charging in residential areas.', '개봉역 주변 안내조는 야간 통과에 필요한 조명과 주거지 충전용 전력을 두고 배정 순서를 정한다.', 'The residents of Gaebong 1-dong negotiate the cost of their next choice: securing lighting for the peak return hours.', '개봉1동 주민들은 다음 선택의 비용을 협의한다: 귀환 집중 시간의 조명을 확보한다.', 1, 1126120.9027494637, 8825.34013509122);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153075000', 271, 'Gaebong 2-dong', '개봉2동', 'Guro-gu', '구로구', 'M295.11,737.36 L295.42,738.89 L291.74,746.6 L280.37,753.71 L276.38,754.36 L267.87,756.46 L258.31,757.14 L245.59,757.45 L244.16,757.28 L237.49,755.21 L237.98,742.88 L238.97,738.11 L245.14,736.3 L252.32,735.9 L258.73,737.49 L265.45,739.62 L267.62,741.47 L269.55,741.96 L280.73,742.9 L283.59,742.76 L295.11,737.36 Z', 'held', '["free-city"]', 'Gaebong 2-dong is free-city land with no station of its own and belongs to a neighboring station''s territory, from which it receives food and fuel. The residents'' work crew shares one stock of spare parts with the apartment repair team for the Gaebong 1 drainage station and the apartment complexes. In the apartments, better-off households live on the underground levels and the poorer ones on the cold upper floors. At night the windows are covered so that outside machines are not drawn.', '개봉2동은 자체 역이 없는 자유도시의 땅으로, 이웃 역 구역에 속해 식량과 연료를 받는다. 주민 작업반은 개봉1 배수 시설과 아파트 단지를 고치는 수리조와 같은 부품 재고를 나눠 쓴다. 아파트에서는 형편이 나은 가구가 지하 층에, 가난한 가구가 추운 위층에 산다. 밤에는 밖의 기계가 끌려오지 않도록 창을 가린다.', 'On opening day, the Gaebong 2-dong work crew first checks the heating equipment on the apartments'' underground levels, then opens the spare-parts bins and counts them.', '개막일 개봉2동 작업반은 아파트 지하 층의 난방 설비부터 점검하고, 부품 재고 상자를 열어 수를 센다.', 0, 815051.06265768, 10704.72808360038);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153076000', 272, 'Gaebong 3-dong', '개봉3동', 'Guro-gu', '구로구', 'M252.61,783.47 L249.96,785.96 L248.02,787.06 L245.71,787.33 L242.63,786.93 L237.56,785.26 L237.37,784.89 L237.65,784.38 L242.27,778.94 L235.75,776.2 L230.67,772.99 L227.39,769.3 L232.37,760.05 L235.98,756 L237.49,755.21 L244.16,757.28 L245.59,757.45 L258.31,757.14 L267.87,756.46 L276.38,754.36 L280.37,753.71 L276.85,755.73 L276.11,756.47 L266.16,770.37 L264.8,771.81 L261.36,772.56 L252.61,783.47 Z', 'held', '["free-city"]', 'The residents around the Mokgamcheon want to set up a separate shift for pedestrian guidance to reduce how often children and luggage are carried on the same handcart.', '목감천 주변 주민들은 아이와 짐을 같은 손수레로 옮기는 일을 줄이려고 보행 안내 교대를 따로 두려 한다.', 'The residents of Gaebong 3-dong negotiate the cost of their next choice: separating handover times for vulnerable pedestrians.', '개봉3동 주민들은 다음 선택의 비용을 협의한다: 취약 보행자의 인계 시간을 분리한다.', 0, 848048.0869609845, 6538.072646174232);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153077000', 273, 'Oryu 1-dong', '오류1동', 'Guro-gu', '구로구', 'M210.79,719.86 L218.28,720.32 L226.26,721.89 L238.34,729.29 L242.84,733.03 L245.14,736.3 L230.16,740.98 L228.77,742.35 L226.01,743.19 L208.7,745.28 L206.69,740.5 L205.36,734.35 L198.31,728.94 L197.9,728.36 L197.5,725.83 L197.84,724.5 L201.04,720.55 L202.03,719.4 L203.55,718.36 L205.47,718.37 L209.69,720.16 L210.79,719.86 Z', 'held', '["free-city"]', 'At Oryu Market, a repairer sets up an inspection table so that usable parts and salvaged metal are not exchanged at the same value.', '오류시장에서는 쓸 수 있는 부품과 회수 금속을 같은 값으로 교환하지 않으려 수리공이 검사대를 마련한다.', 'The residents of Oryu 1-dong negotiate the cost of their next choice: inspecting parts for household equipment first.', '오류1동 주민들은 다음 선택의 비용을 협의한다: 생활 설비용 부품부터 검사한다.', 1, 746743.6133857409, 9250.966297091749);
