INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153079000', 275, 'Sugung-dong', '수궁동', 'Guro-gu', '구로구', 'M204.01,718.29 L202.03,719.4 L197.84,724.5 L197.49,726.66 L198.31,728.94 L205.36,734.35 L206.69,740.5 L208.7,745.28 L192.7,745.48 L192.7,744.99 L191.94,744.95 L176.75,744.89 L176.31,745.08 L176.43,751.9 L176.95,752.08 L175.17,754.15 L168.36,760.52 L165.34,761.84 L164.63,756.41 L157.54,753.26 L152.64,750.33 L150.67,750.55 L145.18,747.46 L144.2,745.13 L140.77,744.66 L140.53,739.5 L136.8,733.51 L139.76,730.26 L140.81,726.25 L143.14,727.23 L145.29,728.71 L146.96,728.09 L151.88,724.27 L153.99,724.98 L156.32,723.08 L155.26,718.49 L157.66,714.62 L161.66,712.91 L161.46,709.4 L164.21,698.48 L163.64,692.98 L175.23,688.93 L175.97,688.95 L187.83,693.26 L187.72,695.91 L193.41,702.45 L198.24,707.03 L202.12,708.43 L203.48,709.69 L204.17,711.79 L204.44,717.14 L204.01,718.29 Z', 'held', '["free-city"]', 'The production team at Yerim Design High School rewrites the old route guidance and wants to make signs that even residents who have difficulty reading can recognize.', '예림디자인고등학교의 제작조는 낡은 길 안내를 다시 쓰며 글을 읽기 어려운 주민도 알아볼 표지를 만들려 한다.', 'The residents of Sugung-dong negotiate the cost of their next choice: cross-checking the on-site residents against the guidance signs.', '수궁동 주민들은 다음 선택의 비용을 협의한다: 현장 주민과 안내 표지를 대조한다.', 1, 2654011.032891268, 2440.3440376599756);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1153080000', 276, 'Hang-dong', '항동', 'Guro-gu', '구로구', 'M168.36,760.52 L173.86,762.79 L179.09,763.03 L180.21,765.02 L180.16,767.38 L182.12,771.74 L185.15,772.64 L186.57,776.61 L191.24,778.37 L191.22,782.08 L187.64,788.14 L191.31,789.59 L190.91,792.21 L192.5,795.97 L191.89,798.79 L190.28,801.26 L184.09,804.39 L183.03,805.99 L181.54,806.51 L173.55,803.76 L171.15,804.04 L168.44,806.14 L164,807.25 L161.21,809.22 L159.92,805.8 L154.18,806.1 L153.95,808.47 L154.96,809.86 L151.96,809.62 L152.54,813.37 L150.39,815.75 L150.13,816.89 L148.62,816.79 L148.01,815.29 L146.77,814.11 L143.14,813.76 L141.32,811.37 L141.68,807.37 L142.92,804.97 L145.22,804.03 L145.17,802.58 L148.01,799 L151.3,798.94 L155.28,791.29 L156.35,785.95 L155.02,782.52 L155.03,772.59 L160.39,770.03 L163.36,768.09 L166.67,764.48 L165.41,763.28 L165.34,761.84 L168.36,760.52 Z', 'held', '["free-city"]', 'The creative community in the Hang-dong Elementary School yard repairs carrying equipment and household tools together to keep ground access open. They do not leave living logistics empty just because no station object has been assigned.', '항동초등학교 마당의 창작 공동체는 지상 접근을 유지하기 위해 운반 장비와 가구 공구를 함께 보수한다. 역 객체가 배정되지 않았다는 이유로 생활 물류를 비워 두지 않는다.', 'The residents of Hang-dong negotiate the cost of their next choice: repairing the shared carrying equipment first.', '항동 주민들은 다음 선택의 비용을 협의한다: 공용 운반 장비부터 보수한다.', 0, 1433226.0149478214, 3339.040702644674);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154551000', 277, 'Gasan-dong', '가산동', 'Geumcheon-gu', '금천구', 'M335.23,775.42 L344.35,783.35 L350.83,791.91 L352.52,793.57 L354.62,795 L358.43,796.34 L371.03,799.11 L374.06,799.33 L375.9,809.08 L368.79,813.47 L368.22,821.72 L362.46,821.41 L348.83,822.3 L354.42,838.42 L355.23,844.93 L347.65,848.76 L330.28,822.83 L324.06,812.52 L318.95,802.19 L316.03,795.26 L311.21,781.36 L311.45,775.18 L313.65,774 L318.24,773.23 L323.3,770.79 L330.63,772 L335.23,775.42 Z', 'held', '["free-city"]', 'Around the Gasan Digital Complex in Gasan-dong, two free-city stations count people and food. Mechanics repair heaters and shutter motors at the industrial cooperative complex and collect parts at Compuzone Gasan branch. Because Bongam Villa and Onnuri Apartments share the same weak power, every extra hour of night work adds light and heat that could draw outside machines.', '가산동 가산디지털단지 주변에는 자유도시의 역 두 곳이 사람과 식량을 센다. 정비공들은 산업협동화 단지에서 난방기와 덧문 모터를 고치고 컴퓨존 가산점에서 부품을 모은다. 봉암빌라와 온누리아파트가 같은 약한 전력을 나눠 쓰기 때문에 야간 작업이 늘수록 바깥 기계를 끌 빛과 열이 더 생긴다.', 'On opening day, some of the heaters work, but food and cloth are short, and the residents debate whether to limit night work at all.', '개막일 난방기 일부는 돌아가지만 식량과 천이 모자라고, 주민들은 야간 작업을 아예 줄일지 논의한다.', 2, 2242563.537841465, 3429.8693750293887);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154561000', 278, 'Doksan 1-dong', '독산1동', 'Geumcheon-gu', '금천구', 'M380.06,824.69 L377.9,852.93 L378.15,856.29 L379.96,862.9 L381.88,868 L376.34,869.98 L365.66,875.2 L366.88,880.19 L368.25,884.06 L370.6,888.74 L371.66,891.74 L369.45,892.6 L368.33,892.23 L364.17,894.79 L355.55,893.18 L355.15,891.73 L348.59,881.54 L346.34,879.27 L345.84,877.92 L343.26,865.35 L345.51,863.27 L347.29,862.08 L350.01,861.55 L352.22,862.64 L352.96,862.63 L353.57,862.31 L354.26,860.62 L353,856.73 L347.65,848.76 L355.23,844.93 L354.42,838.42 L348.83,822.3 L362.46,821.41 L368.22,821.72 L368.79,813.47 L375.9,809.08 L374.06,799.33 L382.93,797.6 L380.06,824.69 Z', 'held', '["free-city"]', 'Between Doksan Station and the community center, workers going to Gasan and neighbors from the sloped housing share the same alleys. Residents use the first floor of Homeplus Geumcheon Store as a shared kitchen and food counting space, and the Dusan Elementary School playground as a gathering point. The Geumcheon Interchange gate checks carts so no lights show on them.', '독산역과 주민센터 사이 골목은 가산으로 일하러 가는 사람들과 사면 주거지 이웃이 함께 쓴다. 주민들은 홈플러스금천점 1층을 공동 취사와 식량 확인 공간으로, 두산초 운동장을 모이는 장소로 쓴다. 금천 나들목 초소는 손수레를 검사해 불빛이 새지 않게 한다.', 'On opening day, the community center posts temporary shift sheets. The shared kitchen runs only in the morning, and the interchange lets in only covered handcarts.', '개막일 주민센터는 임시 교대표를 붙인다. 공동 취사장은 오전만 열고 나들목은 불빛을 가린 손수레만 들인다.', 1, 1962963.920287514, 7295.498328824322);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154562000', 279, 'Doksan 2-dong', '독산2동', 'Geumcheon-gu', '금천구', 'M421.31,845.63 L417.07,847.11 L414.12,845.43 L413.36,845.63 L406.48,849.95 L398.08,857.66 L393.87,857.96 L392.88,859.99 L392.63,863.78 L390.69,867.9 L385.87,872.46 L383.64,873.14 L379.96,862.9 L378.15,856.29 L377.9,852.93 L378.86,842.35 L390.65,842.59 L400.92,840.76 L405.13,839.26 L407.84,839.63 L421.21,844.43 L421.31,845.63 Z', 'held', '["free-city"]', 'Residents of Gungjeon Village and Hojeong Tower carry food and firewood up the stairs from Siheung-daero. The icy slope makes every stair a risk, and there is no station here, so goods are checked at a neighboring dong. After dusk, upper windows stay dark.', '궁전빌리지와 호정타워 주민들은 시흥대로에서 받은 식량과 땔감을 계단으로 나른다. 얼어붙은 사면이라 계단마다 위험하고, 이곳에는 역이 없어 짐은 이웃 동에서 검사받는다. 해가 지면 위층 창은 어둡게 둔다.', 'A temporary order is set. Three railings at Gungjeon Village wobble, but only one morning shift of workers can repair them in the Doksan Elementary School yard.', '임시 순서를 정한다. 궁전빌리지 난간 세 곳이 흔들리지만 독산초 마당에서 수리할 인력은 아침 한 교대뿐이다.', 0, 615743.012708557, 8265.136420490437);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154563000', 280, 'Doksan 3-dong', '독산3동', 'Geumcheon-gu', '금천구', 'M406.9,821.77 L403.91,822.81 L394.93,821.41 L387.05,825.22 L380.06,824.69 L382.93,797.6 L384.44,792.6 L387.88,796.29 L413.87,790.61 L411.25,796.02 L411.24,798.1 L413.12,800.49 L416.46,800.88 L419.25,800.66 L420.13,805.2 L419.24,810.19 L417.25,816.16 L416.82,816.72 L406.9,821.77 Z', 'held', '["free-city"]', 'Merchants at Nammun Market trade insulating cloth from Gasan for grain and kimchi jars brought from the housing slopes. The market is where cold-season food is weighed and counted, and the doctors of the neighborhood come by for the weak. At night, shutters are closed so the market''s warmth does not draw outside machines.', '남문시장 상인들은 가산 쪽에서 온 방한 천을 주거지에서 가져온 곡물과 김치통으로 바꾼다. 시장은 겨울 식량을 달고 세는 곳이고, 동네 의사가 약한 사람들을 보러 들른다. 밤에는 시장의 온기가 바깥 기계를 끌지 않게 덧문을 닫는다.', 'Nammun Market uses a temporary exchange board instead of fixed prices. Checking is possible only in the morning, and the residents of Hanyang Suzain discuss closing the market side of their shutters earlier.', '남문시장은 고정 가격 대신 임시 교환표를 쓴다. 검수는 오전만 가능하고 한양수자인 주민들은 시장 쪽 덧문을 더 일찍 닫는 방안을 논의한다.', 0, 945297.0321387636, 7146.3251976108495);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154564000', 281, 'Doksan 4-dong', '독산4동', 'Geumcheon-gu', '금천구', 'M421.21,844.43 L407.84,839.63 L405.13,839.26 L400.92,840.76 L390.65,842.59 L378.86,842.35 L380.06,824.69 L387.05,825.22 L394.93,821.41 L403.91,822.81 L409.39,820.54 L410.55,822.5 L414.75,833.37 L418.98,842.2 L421.21,844.43 Z', 'held', '["free-city"]', 'The seats of the Gumin Culture and Sports Center Theater are the winter night shelter for slope households such as Taeyeong Villa. Residents want to keep them for the old and the children, and the patrol wants to use some seats for its own watch, so turns must be agreed. Jeongsim Elementary School''s yard is where daytime food is counted, and everyone fears that someone in a crowded shelter could be taken away.', '구민문화체육센터극장의 객석은 태영빌라 같은 사면 가구의 겨울 밤 대피소다. 주민들은 노인과 아이를 위해 남기려 하고 순찰대는 일부를 감시 자리로 쓰려 해서 차례를 정해야 한다. 정심초 운동장은 낮에 식량을 세는 곳이고, 모두가 붐비는 대피소에서 누군가 끌려갈까 걱정한다.', 'On opening day, the community center posts temporary turns for the theater shelter.', '개막일 주민센터는 극장 대피소의 임시 순번을 붙였다.', 0, 619149.1204341935, 6674.482549699792);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154567000', 282, 'Siheung 1-dong', '시흥1동', 'Geumcheon-gu', '금천구', 'M402.3,898.69 L401.63,902.53 L400.68,904.1 L398.88,905.6 L393.62,907.22 L395.08,912.21 L395.44,914.54 L395.21,915.08 L387.03,921.73 L385.93,922.22 L383.67,922.02 L380.06,921.05 L374.05,916.72 L371.15,907.42 L370.45,898.69 L368.33,892.23 L369.45,892.6 L371.66,891.74 L370.6,888.74 L368.25,884.06 L366.88,880.19 L365.66,875.2 L376.34,869.98 L381.88,868 L383.64,873.14 L385.87,872.46 L390.69,867.9 L392.63,863.78 L392.88,859.99 L393.87,857.96 L398.08,857.66 L398.76,860.37 L402.66,885.56 L402.95,888.59 L402.3,898.69 Z', 'held', '["free-city"]', 'When the frozen Siheungcheon spills ice into the back alleys of Daemyeong Market, trade and the walk to Geumcheon-gu Office Station stop together. One free-city station counts people there. The community center sets the order for streamside households, and the Siheung Elementary School yard is a place to break ice and stack sandbags.', '얼어붙은 시흥천이 대명시장 뒷골목으로 얼음을 넘기면 장사와 금천구청역 방향 통행이 함께 멈춘다. 그곳에서는 자유도시의 역 한 곳이 사람을 센다. 주민센터는 천변 가구의 순서를 정하고, 시흥초 운동장은 얼음을 깨고 모래주머니를 쌓는 곳이다.', 'On opening day, Geumcheon-gu Office Station keeps daytime passage open, and the notice about closing it at night is posted only on the Samgeori bulletin board.', '개막일 금천구청역은 낮 통행을 열어 두고, 밤에 닫는다는 알림은 삼거리 게시판에만 붙어 있다.', 1, 1475868.6223250686, 6291.007112389839);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154568000', 283, 'Siheung 2-dong', '시흥2동', 'Geumcheon-gu', '금천구', 'M466.58,903.46 L457.96,911.22 L453.29,914.34 L445.66,923.36 L421.47,907.72 L421,907.32 L420.3,903.8 L421.53,898.82 L424.73,891.56 L425.91,890.51 L427.48,891.06 L428.21,890.95 L432.56,888.3 L437.57,882.31 L438.35,877.67 L438.25,876.39 L449.9,876.15 L449.78,878.01 L450.35,882.29 L451.89,886.31 L462.98,896.24 L467.76,901.66 L466.58,903.46 Z', 'held', '["free-city"]', 'Frozen rockfall piles on the walk up to Byeoksan Complex 3 and Building 508 and slows people coming home with food and fuel. The dong has no station of its own. Residents argue whether to use their labor on ropes below Kalbawi or on the shelter floor of Geumcheon Comprehensive Welfare Town.', '벽산3단지와 508동으로 오르는 길에 얼어붙은 낙석이 쌓여 식량과 연료를 들고 오는 사람들이 늦어진다. 이 동에는 자체 역이 없다. 주민들은 칼바위 아래 밧줄 작업과 금천종합복지타운의 대피 마루 중 어디에 인력을 쓸지 논의한다.', 'On opening day, one lane of the sidewalk below Kalbawi is blocked by stone, and the shelter floor at the Welfare Town can open only until the afternoon.', '개막일 칼바위 아래 인도 한 줄은 돌에 막혀 있고 복지타운 대피 마루는 오후까지만 열 수 있다.', 0, 1179303.9872674432, 5003.2901301994025);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154569000', 284, 'Siheung 3-dong', '시흥3동', 'Geumcheon-gu', '금천구', 'M428.72,937.91 L426.17,937.95 L425.56,938.48 L420.47,943.13 L417.54,946.88 L416.02,950.27 L414.73,954.55 L411.06,959.63 L408.44,960.72 L405.67,961.03 L397.73,959.3 L390.47,950.93 L383.23,944.51 L381.81,942.12 L381.36,940.3 L382.45,939.25 L382.53,934.07 L382.02,929.24 L380.06,921.05 L384.47,922.18 L385.93,922.22 L387.03,921.73 L395.21,915.08 L395.44,914.54 L394.74,911.13 L405.88,916.96 L423.85,931.28 L428.72,937.91 Z', 'held', '["free-city"]', 'Siheung 3-dong is free-city land with no station of its own and belongs to a neighboring station''s territory. Bakmisarang Village Hall keeps the temporary ledger for sharing out food and stove fuel. The frozen paths around Bullocheon Spring and Geumcheon Falls Park are patrolled only rarely. Because outside machines can be drawn by light and heat, residents keep lamps and fires low at night.', '시흥3동은 자체 역이 없는 자유도시의 땅으로 이웃 역 구역에 속한다. 박미사랑마을회관이 식량과 난로 연료를 나누는 임시 장부를 맡는다. 불로천약수터와 금천폭포공원 일대는 길이 얼어붙어 순찰이 드물다. 밖의 기계는 빛과 열에 끌려올 수 있어서 주민들은 밤에 등불과 불씨를 낮춘다.', 'On opening day, Bakmisarang Village Hall opens its temporary food-and-fuel ledger and residents line up. Geumcheon Ramp accepts light handcarts only in the daytime and its night post stands empty, so worried residents go out in pairs for fear of kidnapping.', '개막일 박미사랑마을회관이 식량·연료 임시 장부를 열고 주민들이 줄을 선다. 금천램프는 가벼운 손수레를 낮에만 받고 야간 초소는 비어 있어, 납치가 걱정된 주민들은 둘씩 짝지어 다닌다.', 0, 1334898.4553945572, 2217.0225668028493);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154570000', 285, 'Siheung 4-dong', '시흥4동', 'Geumcheon-gu', '금천구', 'M425.06,847.08 L422.98,850.23 L422.48,851.77 L426.06,872.96 L423.41,873.08 L415.41,877.9 L413.74,880.01 L410.67,890.33 L402.95,888.59 L398.76,860.37 L398.08,857.66 L406.48,849.95 L413.36,845.63 L414.12,845.43 L417.07,847.11 L421.31,845.63 L425.06,847.08 Z', 'held', '["free-city"]', 'The carrying team between Sunheung Spring and Sangiseuk Park B, now covered in snow, brings firewood and food to Geumgang Apartments and Siheung Samik Apartments. Residents hand things over on Doksan-ro 22-gil and in the Sinheung Elementary School yard. The park path is dangerous after dark, so it is used only in the morning.', '눈 덮인 순흥약수터와 산기슭공원B 사이를 오가는 운반조가 금강아파트와 시흥 삼익아파트에 땔감과 식량을 가져다 준다. 주민들은 독산로22길과 신흥초 운동장에서 물건을 주고받는다. 공원 길은 해 진 뒤 위험해서 아침에만 쓴다.', 'On opening day, two rooftop chimneys at Geumgang Apartments are tilted and must be repaired first, and World Meridian''s residents are still discussing when to close their shutters.', '개막일 금강아파트 옥상 연통 두 개가 기울어 먼저 고쳐야 하고, 월드메르디앙 주민들은 덧문을 언제 닫을지 아직 논의 중이다.', 0, 770696.111295481, 7071.269622522559);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1154571000', 286, 'Siheung 5-dong', '시흥5동', 'Geumcheon-gu', '금천구', 'M438.25,876.39 L437.57,882.31 L432.56,888.3 L428.21,890.95 L427.48,891.06 L425.91,890.51 L424.73,891.56 L421.53,898.82 L420.3,903.22 L420.35,904.37 L421,907.32 L421.47,907.72 L445.66,923.36 L445.27,925.17 L442.26,933.37 L440.81,935.39 L436.85,938.54 L428.72,937.91 L423.85,931.28 L405.88,916.96 L394.74,911.13 L393.62,907.22 L398.88,905.6 L400.68,904.1 L401.63,902.53 L402.3,898.69 L402.95,888.59 L410.67,890.33 L413.74,880.01 L415.41,877.9 L423.41,873.08 L426.06,872.96 L428,874.51 L438.25,876.39 Z', 'held', '["free-city"]', 'The tilted retaining wall of Yaksu Villa threatens the footing on Siheung-daero 40-gil. The same workers are needed for repairs at Sindo Brenua Apartments and for the wall. Geumcheon Elementary School''s yard is the daytime food stand, and the Hwain Electronics Industry site is a spot to recover circuit boards for heater and shutter latches.', '약수빌라의 기운 옹벽이 시흥대로40길 길을 위협한다. 신도브래뉴아파트 수리와 옹벽 보수에 같은 작업자가 필요하다. 금천초 운동장은 낮 식량 나눔 장소이고, 화인전자산업 터는 난방기와 덧문 걸쇠에 쓸 기판을 회수하는 곳이다.', 'The community center puts households with wall cracks at the top of its list. One side of the piles at Yaksu Villa is lifted, the Geumcheon Elementary School food stand runs only in the morning, and night entry to the Hwain Electronics site is halted.', '주민센터는 옹벽 균열이 있는 가구를 명단 맨 위에 올렸다. 약수빌라 말뚝 한쪽이 들떠 있고 금천초 식량 나눔은 오전만 하며 화인전자 터의 야간 출입은 중단했다.', 0, 1425853.1633702496, 3595.3211254115886);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156051500', 287, 'Yeongdeungpo-bondong', '영등포본동', 'Yeongdeungpo District', '영등포구', 'M416.18,683.51 L415.93,676.92 L408.56,677.52 L403.74,681.84 L401.92,684.4 L392.13,685.88 L388.47,677.73 L381.4,680.59 L380.37,678.74 L398.23,669.24 L397.84,668.18 L403.9,665.52 L418.91,660.96 L432.48,659.99 L434.56,659.32 L434.66,660.62 L436.22,665.37 L437.49,668 L439.09,669.75 L440.76,670.99 L437.66,675.8 L435.59,678.34 L432.69,679.47 L416.18,683.51 Z', 'held', '["free-city"]', 'The handover teams around Yeongdeungpo Station do not want to receive long-distance supplies and residents'' rations in the same order. Once unloading of large freight begins, stretcher handovers toward Yosep Clinic get backed up.', '영등포역 주변 인계조는 장거리 물자와 주민 배급을 같은 순서로 받지 않으려 한다. 큰 화물의 하역이 시작되면 요셉의원 쪽 들것 인계가 밀린다.', 'Residents of Yeongdeungpo-bondong negotiate the cost of their next choice: clearing the daily-life handover section first.', '영등포본동 주민들은 다음 선택의 비용을 협의한다: 생활 인계 구간을 먼저 비운다.', 1, 807639.8017261397, 7499.258935796913);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156053500', 288, 'Yeongdeungpo-dong', '영등포동', 'Yeongdeungpo District', '영등포구', 'M424.82,634.2 L432.79,648.92 L437.01,652.16 L434.56,659.32 L432.48,659.99 L418.91,660.96 L403.9,665.52 L397.84,668.18 L396.56,667.89 L395.06,666.97 L394.13,665.94 L392.84,663.46 L390.92,657.02 L389.76,651.84 L389.76,648.42 L393.09,634.63 L395.15,627.88 L402.82,606.23 L405.51,605.53 L405.81,606.5 L405.4,621.97 L406.02,625.74 L407.11,629.58 L408.38,629.91 L412.51,627.96 L416.58,627.27 L419.68,628.83 L422.73,635.36 L424.82,634.2 Z', 'held', '["free-city"]', 'Merchants around Yeongdeungpo Market want to separate the goods they will sell today from the rations residents have already reserved.', '영등포시장 주변 상인들은 오늘 팔 물건과 이미 예약한 주민 배급분을 분리하려 한다.', 'Residents of Yeongdeungpo-dong negotiate the cost of their next choice: storing the reserved ration portions separately.', '영등포동 주민들은 다음 선택의 비용을 협의한다: 배급 예약분을 별도 보관한다.', 2, 1414765.2805348213, 6618.695078847411);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156054000', 289, 'Yeoui-dong', '여의동', 'Yeongdeungpo District', '영등포구', 'M451.68,573.28 L453.34,576.14 L466.5,581.86 L474.09,573.66 L489.95,582.12 L505.37,591.37 L515.22,601.15 L526.5,619.95 L529.35,626.42 L528.9,658.6 L499.73,664.47 L478.95,666.08 L461.35,664.37 L459.17,663.86 L443.43,656.49 L439.34,654.11 L432.79,648.92 L421.36,627.55 L420.38,623.6 L413.83,604.64 L409.77,599.08 L405.86,581.18 L401.65,573.21 L436.38,573.06 L451.68,573.28 Z', 'held', '["free-city"]', 'Yeoui-dong has five free-city stations, and residents around Yeouinaru and Saetgang count who and what comes in from the frozen river. A wide ice surface is not a road, so only confirmed walking routes are used. Doctors and mechanics have their own posts, and shutters drop at dusk.', '여의동에는 자유도시의 역이 다섯 곳 있고, 여의나루와 샛강 주변 주민들이 얼어붙은 강에서 들어오는 사람과 짐을 센다. 넓은 얼음판은 길이 아니어서 확인된 보행로만 쓴다. 의사와 정비공이 각자의 자리를 지키고 해 질 녘에는 덧문이 내려간다.', 'On opening day, Yeoui-dong residents move the waiting area to higher ground away from the river wind.', '개막일 여의동 주민들은 대기 구획을 강바람이 덜한 높은 쪽으로 옮긴다.', 5, 8202924.467414119, 1240.3137491289497);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156055000', 290, 'Dangsan 1-dong', '당산1동', 'Yeongdeungpo District', '영등포구', 'M393.37,633.71 L389.76,648.42 L390,653.35 L388.56,652.46 L385.98,651.69 L364.69,647.07 L362.21,642.75 L365.93,623.75 L370.31,616.59 L379.12,621.92 L395.15,627.88 L393.37,633.71 Z', 'held', '["free-city"]', 'The handover team at Yeongdeungpo-gu Office Station records supplies received from nearby housing complexes and labor promises separately, to clarify responsibility for parts exchange.', '영등포구청역 인계조는 주변 단지에서 받은 물자와 노동 약속을 별도 기록해 부품 교환의 책임을 분명히 한다.', 'Residents of Dangsan 1-dong negotiate the cost of their next choice: separating supply receipt from labor reservations.', '당산1동 주민들은 다음 선택의 비용을 협의한다: 물자 수령과 노동 예약을 구분한다.', 1, 742955.2693944721, 8468.746718935128);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156056000', 291, 'Dangsan 2-dong', '당산2동', 'Yeongdeungpo District', '영등포구', 'M405.86,581.18 L409.77,599.08 L413.83,604.64 L420.38,623.6 L421.36,627.55 L424.82,634.2 L422.73,635.36 L419.68,628.83 L416.58,627.27 L412.51,627.96 L408.38,629.91 L407.11,629.58 L406.02,625.74 L405.4,621.97 L405.81,606.5 L405.51,605.53 L402.82,606.23 L395.15,627.88 L379.12,621.92 L370.31,616.59 L389.47,586.44 L371.04,570.05 L374.88,571.25 L377.44,567.19 L381.12,568.7 L383.9,568.09 L387.51,571.33 L390.07,569.67 L389.39,567.57 L393.68,563.27 L401.65,573.21 L405.86,581.18 Z', 'held', '["free-city"]', 'The guide team around Dangsan Station wants to set up a rest area that waiting residents and freight porters can share. If every seat is removed to widen the passage, residents with difficulty moving will struggle to hold out.', '당산역 주변 안내조는 기다리는 주민과 화물 짐꾼이 함께 쓸 휴식 공간을 마련하려 한다. 통로를 늘리려고 모든 자리를 없애면 거동이 어려운 주민이 버티기 어렵다.', 'Residents of Dangsan 2-dong negotiate the cost of their next choice: securing care waiting seats beside the passage.', '당산2동 주민들은 다음 선택의 비용을 협의한다: 돌봄 대기석을 통로 옆에 확보한다.', 2, 1633785.755608449, 6651.178076866693);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156058500', 292, 'Dorim-dong', '도림동', 'Yeongdeungpo District', '영등포구', 'M416.18,683.51 L381.43,702.62 L372.67,692.42 L366.48,687.67 L381.4,680.59 L388.47,677.73 L392.13,685.88 L401.92,684.4 L403.74,681.84 L408.56,677.52 L415.93,676.92 L416.18,683.51 Z', 'held', '["free-city"]', 'The repair crew managing the toolbox at Dorim-dong Community Center wants to let even households with few supplies borrow tools. The management team, which demands collateral, and residents who offer to pay back with labor are negotiating.', '도림동 주민센터의 공구함을 관리하는 수리반은 물자가 적은 가구도 대여할 수 있게 하려 한다. 담보를 요구하는 관리조와 노동으로 갚겠다는 주민이 협의한다.', 'Residents of Dorim-dong negotiate the cost of their next choice: recognizing repair labor as payment for rentals.', '도림동 주민들은 다음 선택의 비용을 협의한다: 수리 노동을 대여 대가로 인정한다.', 0, 549408.5157642954, 9566.105819617065);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156060500', 293, 'Mullae-dong', '문래동', 'Yeongdeungpo District', '영등포구', 'M382.91,650.93 L388.18,652.31 L390,653.35 L392.3,661.82 L393.54,664.94 L395.06,666.97 L396.56,667.89 L397.84,668.18 L398.23,669.24 L380.37,678.74 L381.4,680.59 L366.48,687.67 L362.99,686.18 L359.95,680.89 L356.96,678.16 L334.42,664.59 L327.96,661.1 L329.02,644.52 L343.92,647.47 L344.95,643.14 L382.91,650.93 Z', 'held', '["free-city"]', 'The fabrication team around Mullae Station wants to extend metalworking hours, but nearby camping households demand time to rest at night.', '문래역 주변 제작조는 금속 작업 시간을 늘리려 하지만 가까운 숙영 가구는 밤에 쉴 시간을 요구한다.', 'Residents of Mullae-dong negotiate the cost of their next choice: grouping noisy work into the daytime.', '문래동 주민들은 다음 선택의 비용을 협의한다: 시끄러운 작업을 주간에 모은다.', 1, 1741661.1476546992, 5349.548052183572);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156061000', 294, 'Yangpyeong 1-dong', '양평1동', 'Yeongdeungpo District', '영등포구', 'M370.31,616.59 L365.93,623.75 L362.73,639.77 L362.21,642.75 L364.69,647.07 L361.26,646.68 L344.95,643.14 L343.92,647.47 L329.02,644.52 L329.09,641.59 L331.13,630.69 L334.66,626.77 L345.05,622.18 L347.84,620.61 L349.69,618.46 L354.11,611.06 L358.58,612.32 L370.31,616.59 Z', 'held', '["free-city"]', 'In the space marked as the Suhwa Industrial Complex, salvage teams pick out parts usable for daily-life facilities before dismantling equipment whose function they do not know.', '수화공단으로 표시된 공간에서 회수조는 기능을 모르는 장비를 분해하기 전에 생활 설비에 쓸 수 있는 부품을 골라낸다.', 'Residents of Yangpyeong 1-dong negotiate the cost of their next choice: running a function test before disassembly.', '양평1동 주민들은 다음 선택의 비용을 협의한다: 분해 전에 기능 검사를 한다.', 1, 864132.8560243102, 6817.007314248305);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156062000', 295, 'Yangpyeong 2-dong', '양평2동', 'Yeongdeungpo District', '영등포구', 'M392.47,559.44 L393.68,563.27 L389.39,567.57 L390.07,569.67 L387.51,571.33 L383.9,568.09 L381.12,568.7 L377.44,567.19 L374.88,571.25 L371.04,570.05 L389.47,586.44 L370.31,616.59 L358.58,612.32 L360.03,608.29 L355.07,606.26 L355.07,603.48 L358.6,601.82 L359.28,596.86 L353.79,589.19 L345.89,570.99 L344.88,564.67 L339.46,557.56 L332.25,549.18 L324.95,535.9 L324.58,529.13 L328.04,529.96 L328.41,524.09 L331.5,519.28 L360.74,537.48 L384.65,549.36 L392.47,559.44 Z', 'held', '["free-city"]', 'The big facility lot in Yangpyeong 2-dong is a cold shelter where the free-city mechanics keep old equipment warm for the neighbors. One station counts people and food. The mechanics want to check the machines before running them harder, while the food team urges them to send the day''s warmth first.', '양평2동의 큰 시설 부지는 자유도시 정비공들이 이웃을 위해 낡은 설비의 온기를 지키는 추운 쉼터다. 역 한 곳이 사람과 식량을 센다. 정비공은 설비를 더 돌리기 전에 점검하자고 하고, 식량조는 오늘 필요한 온기부터 보내라고 재촉한다.', 'On opening day, Yangpyeong 2-dong residents post the day''s equipment check and the heat shares side by side.', '개막일 양평2동 주민들은 그날의 설비 점검 결과와 온기 배분을 나란히 게시한다.', 1, 2891935.8102742876, 2318.9311381582656);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156063000', 296, 'Singil 1-dong', '신길1동', 'Yeongdeungpo District', '영등포구', 'M461.35,664.37 L454.14,676.26 L451.02,685.78 L449.99,690.39 L449.86,693.45 L445.51,696.4 L435.7,699.79 L432.77,701.82 L429.06,694.07 L426.06,681.13 L432.69,679.47 L435.59,678.34 L439.16,673.77 L440.76,670.99 L439.09,669.75 L437.49,668 L436.22,665.37 L434.66,660.62 L434.56,659.32 L437.01,652.16 L439.34,654.11 L443.43,656.49 L459.17,663.86 L461.35,664.37 Z', 'held', '["free-city"]', 'The fictional medical team in the Seongae Hospital building wants to fix stretcher handles and wheels first, but the hauling team is also waiting for the same parts.', '성애병원 건물의 창작 의무조는 들것 손잡이와 바퀴부터 고치려 하지만 운반조도 같은 부품을 기다린다.', 'Residents of Singil 1-dong negotiate the cost of their next choice: repairing the damaged stretchers first.', '신길1동 주민들은 다음 선택의 비용을 협의한다: 손상된 들것을 먼저 수리한다.', 1, 811209.8442015207, 6978.465609687171);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156065000', 297, 'Singil 3-dong', '신길3동', 'Yeongdeungpo District', '영등포구', 'M412.02,706.81 L410.96,705.82 L408.03,704.87 L395.25,706.77 L389.09,710.05 L387.86,710.97 L381.43,702.62 L416.18,683.51 L417.85,690.14 L418.08,701.11 L415.64,708.24 L412.02,706.81 Z', 'held', '["free-city"]', 'The fictional laundry team in the Dorim Elementary School yard wants to wash work clothes and camp bedding on the same day, but there is not enough drying space.', '도림초등학교 마당의 창작 세탁조는 작업복과 숙영 침구를 같은 날 씻으려 하지만 건조 자리는 충분하지 않다.', 'Residents of Singil 3-dong negotiate the cost of their next choice: dividing drying time for bedding and work clothes.', '신길3동 주민들은 다음 선택의 비용을 협의한다: 침구와 작업복의 건조 시간을 나눈다.', 0, 480059.52018029516, 10028.756430435675);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156066000', 298, 'Singil 4-dong', '신길4동', 'Yeongdeungpo District', '영등포구', 'M430.82,707.04 L423.61,706.59 L419.56,707.44 L418.81,708.32 L417.84,708.15 L417.07,708.74 L416.27,708.58 L416.33,708.97 L415.79,709.01 L415.64,708.24 L418.22,700.2 L417.85,690.14 L416.18,683.51 L426.06,681.13 L429.06,694.07 L432.77,701.82 L430.82,707.04 Z', 'held', '["free-city"]', 'The cooking team using the remaining kitchen space of Daeyoung High School asks the residents'' meeting whether to pool each household''s stock or accept only ration reservations.', '대영고등학교의 남은 주방 공간을 쓰는 취사조는 가구별 재고를 모을지 배급 예약만 받을지 주민 회의에 묻는다.', 'Residents of Singil 4-dong negotiate the cost of their next choice: booking meals according to the actual incoming volume.', '신길4동 주민들은 다음 선택의 비용을 협의한다: 실제 반입량에 맞춰 식사를 예약한다.', 0, 288071.99496508244, 12238.607228819108);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156067000', 299, 'Singil 5-dong', '신길5동', 'Yeongdeungpo District', '영등포구', 'M415.64,708.24 L415.87,714.75 L414.6,717.52 L412.78,720.31 L411.48,721.36 L410.08,727.67 L409.78,731.19 L407.24,732.24 L397.09,731.67 L395.33,730.7 L393.74,729.14 L389.76,724.1 L389.35,722.79 L391.18,719.96 L392.69,716.74 L387.86,710.97 L389.09,710.05 L395.25,706.77 L408.03,704.87 L410.96,705.82 L412.02,706.81 L415.64,708.24 Z', 'held', '["free-city"]', 'The low alleys around the frozen Daebangcheon in Singil 5-dong ice over first, so residents check each alley and move their food and fuel to higher rooms. There is no station of its own, and goods pass through a neighboring dong''s check. Shutters stay down at night, and families watch for strangers.', '신길5동 대방천 주변 낮은 골목은 가장 먼저 어는 곳이라, 주민들은 골목마다 상태를 확인하고 식량과 연료를 높은 방으로 옮긴다. 자체 역이 없어 짐은 이웃 동의 검사를 거친다. 밤에는 덧문을 내리고 가족들은 낯선 사람을 경계한다.', 'On opening day, Singil 5-dong residents clear the ice in front of the living-supply storeroom first.', '개막일 신길5동 주민들은 생활 창고 앞 얼음부터 먼저 치운다.', 0, 530540.5503920818, 5369.617832029371);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156068000', 300, 'Singil 6-dong', '신길6동', 'Yeongdeungpo District', '영등포구', 'M430.82,707.04 L425.31,715.76 L423.47,716.75 L422.67,717.57 L420.9,720.08 L420.38,721.5 L431.03,721.03 L436.92,715.34 L444.55,716.58 L446.17,717.2 L444.26,728.69 L442.81,730.51 L439.02,731.73 L429.66,734.1 L422.25,735.09 L420.21,736.82 L415.77,745.26 L413.35,748.71 L409.78,731.19 L409.79,729.46 L411.48,721.36 L412.78,720.31 L414.6,717.52 L415.87,714.75 L415.79,709.01 L416.33,708.97 L416.27,708.58 L417.07,708.74 L417.84,708.15 L418.81,708.32 L419.56,707.44 L423.61,706.59 L430.82,707.04 Z', 'held', '["free-city"]', 'The residents'' work team around Sinpung Station decides on posting locations so that travelers from afar can also learn the changed handover times.', '신풍역 주변의 주민 작업반은 바뀐 인계 시간을 멀리서 온 통행객도 알 수 있도록 게시 위치를 정한다.', 'Residents of Singil 6-dong negotiate the cost of their next choice: updating the postings at multiple entrances in the same shift.', '신길6동 주민들은 다음 선택의 비용을 협의한다: 여러 출입구의 게시를 같은 교대에 갱신한다.', 3, 679299.532433488, 7805.834903204767);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156069000', 301, 'Singil 7-dong', '신길7동', 'Yeongdeungpo District', '영등포구', 'M444.55,716.58 L436.92,715.34 L431.03,721.03 L420.38,721.5 L420.9,720.08 L422.67,717.57 L423.47,716.75 L425.31,715.76 L427.96,711.9 L430.82,707.04 L432.77,701.82 L435.7,699.79 L445.51,696.4 L449.86,693.45 L449.99,690.39 L451.02,685.78 L454.14,676.26 L458.9,668.67 L464.31,672.2 L464.42,675.55 L462.43,676.46 L459.51,676.77 L447.11,714.73 L446.17,717.2 L444.55,716.58 Z', 'held', '["free-city"]', 'Around Daebang Station, the fictional guard team and the residents'' representatives want to separate civilian passage checks from service registration. Even if traces of a military organization remain, it is not regarded as having taken over current institutional operations.', '대방역 주변에서 창작 경비조와 주민 대표는 민간 통과 확인을 복무 등록과 분리하려 한다. 군사 조직의 흔적이 있어도 현재 기관 운영을 이어받았다고 보지 않는다.', 'Residents of Singil 7-dong negotiate the cost of their next choice: separating civilian handovers from service consultations.', '신길7동 주민들은 다음 선택의 비용을 협의한다: 민간 인계와 복무 협의를 분리한다.', 4, 547650.1970023683, 10575.181076717397);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156070000', 302, 'Daerim 1-dong', '대림1동', 'Yeongdeungpo District', '영등포구', 'M404.32,761.83 L391.76,749.25 L386.09,740.46 L397.09,731.67 L407.24,732.24 L409.78,731.19 L413.35,748.71 L404.32,761.83 Z', 'held', '["free-city"]', 'The fictional medical team in the Gangnam Seongsim Hospital building must accurately receive explanations from residents who speak different languages. If interpreters are shared with the ration counter, waiting times grow longer.', '강남성심병원 건물의 창작 의무조는 서로 다른 언어를 쓰는 주민의 설명을 정확하게 받아야 한다. 통역을 배급 창구와 나눠 쓰면 대기 시간이 길어진다.', 'Residents of Daerim 1-dong negotiate the cost of their next choice: stationing interpreter shifts for medical requests.', '대림1동 주민들은 다음 선택의 비용을 협의한다: 의무 요청용 통역 교대를 둔다.', 0, 481351.356622442, 8212.504121185424);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156071000', 303, 'Daerim 2-dong', '대림2동', 'Yeongdeungpo District', '영등포구', 'M395.33,775.96 L394,775.87 L387.38,773.46 L382.09,769.6 L379.14,766.46 L372.96,750.19 L386.09,740.46 L391.76,749.25 L404.32,761.83 L395.33,775.96 Z', 'held', '["free-city"]', 'Households along Dorimcheon Stream want to move goods out of the low warehouses, but the distribution team must also handle same-day arrivals.', '도림천을 접한 가구들은 물품을 낮은 창고에서 옮기려 하지만 배급조는 당일 반입도 처리해야 한다.', 'Residents of Daerim 2-dong negotiate the cost of their next choice: moving essential ration stock to higher storage.', '대림2동 주민들은 다음 선택의 비용을 협의한다: 필수 배급 재고를 높은 보관소로 옮긴다.', 0, 578455.9368330662, 5927.331334468561);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1156072000', 304, 'Daerim 3-dong', '대림3동', 'Yeongdeungpo District', '영등포구', 'M381.43,702.62 L392.69,716.74 L391.18,719.96 L389.35,722.79 L389.76,724.1 L393.74,729.14 L395.33,730.7 L397.09,731.67 L386.09,740.46 L372.96,750.19 L370.65,742.19 L367.8,729.93 L367.6,728.02 L367.38,712.67 L368.41,705.85 L368.97,694.82 L372.67,692.42 L381.43,702.62 Z', 'held', '["free-city"]', 'The repair team around Daerim Station wants to return commuters'' equipment in a short time, but residents'' large repairs are also backed up.', '대림역 주변 수선조는 출근 통행객의 장비를 짧은 시간에 돌려주려 하지만 주민의 큰 수리도 밀려 있다.', 'Residents of Daerim 3-dong negotiate the cost of their next choice: booking separate time for urgent residential repairs.', '대림3동 주민들은 다음 선택의 비용을 협의한다: 주거지 긴급 수리 시간을 따로 예약한다.', 1, 936827.3754003235, 6593.850865385233);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159051000', 305, 'Noryangjin 1-dong', '노량진1동', 'Dongjak-gu', '동작구', 'M563.71,676.73 L550.31,687.31 L542.24,695.25 L541.35,695.12 L540.66,694.26 L530.85,694.68 L529.3,697 L522.25,698.71 L508.37,699.83 L502.94,701.06 L502.11,700.44 L503.84,698.13 L507.86,698.1 L508.91,696.96 L512.88,690.74 L512.2,688.44 L509.36,687.14 L506.23,688.8 L502.08,674.9 L498.93,671.46 L499.73,664.47 L528.9,658.6 L550.74,667.37 L563.71,676.73 Z', 'held', '["free-city"]', 'Noryangjin 1-dong has three free-city stations, at Nodeul Platform and Noryangjin Platform among them. Nodeul calls only south-bank crate turns, and Noryangjin holds the waiting seats for travelers. Geonyeong Apartments share the same cold morning heating, so heaters and food counts are argued out in the same shift.', '노량진1동에는 노들 승강장과 노량진 승강장을 포함해 자유도시의 역이 세 곳 있다. 노들은 남안 상자 순번만 부르고, 노량진은 여행자 대기석이다. 건영아파트는 같은 추운 아침 난방을 나눠 쓰기 때문에 난방기와 식량 셈이 같은 교대에서 논의된다.', 'On opening day, Noryangjin 1-dong''s distribution team and mechanics settle which goes first: station heaters, storeroom food, or household fuel.', '개막일 노량진1동의 배급조와 정비공은 역 난방기, 창고 식량, 가구 연료 중 무엇을 먼저 할지 정한다.', 3, 1626496.4462884932, 6162.140730691927);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159052000', 306, 'Noryangjin 2-dong', '노량진2동', 'Dongjak-gu', '동작구', 'M502.94,701.06 L499.06,703.12 L496.49,702.86 L496.14,702.68 L496.11,701.81 L495.03,700.52 L490.61,697.13 L489.51,696.85 L487.66,697.14 L486.54,690.03 L486.57,684.45 L485.27,675.37 L481.47,670.14 L481.49,665.7 L499.73,664.47 L498.93,671.46 L502.08,674.9 L506.23,688.8 L509.36,687.14 L512.2,688.44 L512.88,690.74 L508.23,697.76 L507.86,698.1 L503.84,698.13 L502.11,700.44 L502.94,701.06 Z', 'held', '["free-city"]', 'A construction fence runs between Noryangjin 2-dong Community Center and the Seoul Noryangjin Elementary School yard. The planned lot of the Noryangjin Station Youth Housing Apartments remains an empty lot where stretchers and square timber lie on the same dirt ground, and the planned sites of Rakeullache Jai Deupain and Deupain Areutia likewise read only as piles of timber. The Cheonghwa Hospital building is a fictional waiting-bed ward, and actual medical operation is not read from the tag. Jangseungbaegi-ro 27-gil backs up as far as the front of Leaders Tower when carts get blocked.', '노량진2동주민센터와 서울노량진초등학교 운동장 사이로 공사 펜스가 이어진다. 노량진역청년주택아파트 예정 필지는 빈 터로 남아 들것과 각재가 같은 흙바닥에 놓이고, 라클라체자이드파인·드파인아르티아 예정지도 각재 더미로만 읽힌다. 청화병원 건물은 창작상 대기 침상이며 실제 진료 가동을 태그로 읽지 않는다. 장승배기로27길은 수레가 막히면 리더스타워 앞까지 역류한다.', 'In response to the opening-day supply gap, Noryangjin 2-dong Community Center wants to divide the personnel to assign to vacant lot access and to the fictional waiting room in the Cheonghwa Hospital building.', '노량진2동 주민센터는 개막일 공급 공백에 대응해 공터 출입과 청화병원 건물의 창작 대기실에 배정할 인력을 나누려 한다.', 0, 648502.4106218244, 3419.108338971191);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159053000', 307, 'Sangdo 1-dong', '상도1동', 'Dongjak-gu', '동작구', 'M542.62,698.4 L540.98,708.06 L548.91,725.36 L551.41,727.27 L561.76,730.91 L566.88,742.54 L564.73,743.98 L561.85,749.7 L561.76,746.72 L558.98,744.9 L555.82,744.97 L555.31,745.23 L554.51,748.32 L550.75,752.33 L548.86,753.24 L547.12,753.13 L543.37,754.57 L541.18,755.06 L539.34,754.61 L533.2,750.07 L525.4,745.47 L523,745.23 L522.18,744.61 L523.54,736.82 L524.75,734.03 L524.83,727.37 L523.68,725.38 L523.79,721.28 L521.96,717.87 L519.66,714.53 L524,707.86 L527.8,705.1 L529.35,702.6 L530.91,699.52 L530.47,698.24 L530.85,694.68 L540.66,694.26 L541.35,695.12 L542.62,698.4 Z', 'held', '["free-city"]', 'At the Sangdo and Sungsil University Station platform, only slope turns are called, and the North Gate of Sungsil University is where cots and food parcels part ways. The Seoul Sanghyeon Elementary School yard is the courtyard where empty baskets are sent back. The ground is steep, so the stairs freeze over first after snow.', '상도·숭실대입구 승강장은 비탈 순번만 부르고, 숭실대학교 북문은 침상과 식량 꾸러미가 갈라지는 곳이다. 서울상현초등학교 운동장은 빈 바구니를 돌려보내는 마당이다. 기복이 커서 눈이 온 뒤에는 계단이 가장 먼저 언다.', 'On opening day, Sangdo 1-dong residents and the medical team set shifts for the Sungsil University North Gate handover and for steady food runs along the slope.', '개막일 상도1동 주민과 의무조는 숭실대 북문 인계와 사면 식량 운반에 필요한 교대를 정한다.', 2, 1430071.7985860405, 9218.977685620583);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159054000', 308, 'Sangdo 2-dong', '상도2동', 'Dongjak-gu', '동작구', 'M500.49,720.9 L490.74,710.74 L481.61,709.35 L480.17,707.72 L479.94,706.61 L480.33,702.2 L481.5,702.12 L482.5,703.6 L483.85,703.71 L485.37,702.28 L485.75,700.13 L486.1,699.81 L486.63,698.12 L487.66,697.14 L489.51,696.85 L490.61,697.13 L495.03,700.52 L496.11,701.81 L496.14,702.68 L497.36,703.07 L499.06,703.12 L502.94,701.06 L508.37,699.83 L522.25,698.71 L529.3,697 L530.85,694.68 L530.47,698.24 L530.91,699.52 L529.35,702.6 L527.8,705.1 L524,707.86 L519.66,714.53 L521.96,717.87 L523.79,721.28 L523.68,725.38 L500.49,720.9 Z', 'held', '["free-city"]', 'Jangseungbaegi Platform splits alley food tickets from lower-level cart turns under one roof. Sangdo 2-dong Community Center and Seoul Sinsangdo Elementary School are the food-counting seats, and Sangdo Raemian Complex 1 residents argue over fuel with the households on Sangdo-ro 31-gil. In front of the Guripsangdo Daycare Center, carts jam first.', '장승배기 승강장은 골목 식량표와 하층 수레 순번을 한 지붕에서 나눈다. 상도2동주민센터와 서울신상도초등학교가 식량을 세는 자리이고, 상도 래미안 1차 주민은 상도로31길 가구와 연료를 놓고 협의한다. 구립상도어린이집 앞은 수레가 막히면 먼저 엉킨다.', 'On opening day, Sangdo 2-dong Community Center sets shifts to keep Jangseungbaegi passage and household food counts going together, and handles vacant-lot loading separately.', '개막일 상도2동 주민센터는 장승배기 통행과 가구 식량 확인을 함께 유지할 교대를 정하고 공터 적재는 따로 관리한다.', 1, 776372.5461276938, 10307.16508448489);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159055000', 309, 'Sangdo 3-dong', '상도3동', 'Dongjak-gu', '동작구', 'M478.02,720.56 L488.59,735.06 L500.16,746.45 L505.67,750.48 L499.51,755.4 L498.48,752.85 L489.83,749.84 L482.18,747.57 L475.49,746.1 L471.93,743.98 L470.57,739.13 L470.6,738.09 L471.52,733.26 L472.86,730.18 L471.62,730.28 L468.35,726.45 L469.69,726.03 L473.28,724 L473.53,723.36 L472.77,720.96 L472.07,720.25 L469.28,719.5 L467.7,711.72 L467.83,710.43 L468.7,709.92 L475.67,709.33 L478.41,708.81 L480.17,707.72 L481.61,709.35 L490.74,710.74 L478.02,720.56 Z', 'held', '["free-city"]', 'Seongdae Traditional Market is the scale of alley livelihoods, and the Guksabong slope is the road for firewood and food. Sangdo 3-dong Community Center only records the market seat turns, and the Ganghyeon Middle School yard is where empty baskets are set down. The apartments of Gabeul Myeongga Complex 1 and Daon get fuel later than the market''s morning. The Guksabong 2ra-gil stairs take the day''s labor first.', '성대전통시장은 골목 생업의 저울이고, 국사봉 비탈은 땔감과 식량이 오가는 길이다. 상도3동주민센터는 시장 좌석 순번만 적고, 강현중학교 운동장은 빈 바구니를 내려놓는 마당이다. 갑을명가1차와 다온아파트는 시장의 아침보다 늦게 연료를 받는다. 국사봉2라길 계단이 하루 인력을 먼저 가져간다.', 'Seongdae Market merchants and the Sangdo 3-dong carrying team set the order between market weighing and handovers around Guksabong.', '성대전통시장 상인과 상도3동 운반조는 시장 계량과 국사봉 주변 인계의 순서를 정한다.', 0, 672743.1334020165, 10392.97118447414);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159056000', 310, 'Sangdo 4-dong', '상도4동', 'Dongjak-gu', '동작구', 'M523.85,725.58 L524.83,727.37 L524.75,734.03 L523.54,736.82 L522.18,744.61 L510.66,751.12 L509.06,750.55 L505.67,750.48 L500.16,746.45 L497.8,744.28 L488.59,735.06 L478.02,720.56 L490.74,710.74 L500.49,720.9 L523.85,725.58 Z', 'held', '["free-city"]', 'Sangdo 4-dong Community Center and the Seoul Sangdo Elementary School yard are the alley food-counting yards. Households of Yaksu Mansion and Lotte Castle Bien share fuel along Yangnyeong-ro 26-gil. Gukbongsan Middle School and Seoul Samseong School only hold cots and empty baskets. The ground is rugged, so when a heater breaks, alleys go cold first.', '상도4동주민센터와 서울상도초등학교 운동장이 골목 식량 확인의 마당이다. 약수맨션과 롯데캐슬비엔 가구는 양녕로26길 연료를 나눠 쓴다. 국사봉중학교와 서울삼성학교는 침상과 빈 바구니만 쌓아 둔다. 기복이 커서 난방기가 멈추면 골목이 먼저 식는다.', 'On opening day, Sangdo 4-dong residents first settle the shifts for Yaksu Mansion''s fuel stock and the handover in the school yard.', '개막일 상도4동 주민들은 약수맨션의 연료 비축과 학교 마당 인계에 필요한 교대를 먼저 정한다.', 0, 967793.777056377, 8863.355193386731);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159060500', 311, 'Heukseok-dong', '흑석동', 'Dongjak-gu', '동작구', 'M592.1,707.78 L591.29,708.3 L583.7,710.4 L577.2,716.14 L564.13,732.18 L561.76,730.91 L551.41,727.27 L548.91,725.36 L540.98,708.06 L542.62,698.4 L541.35,695.12 L542.24,695.25 L550.31,687.31 L563.71,676.73 L575.44,685.15 L598.9,696.73 L592.1,707.78 Z', 'held', '["free-city"]', 'Heukseok platform calls only slope turns, and the Daemeorisan stairs are the single line for food buckets and stretchers. Chung-Ang University Seoul Campus and Surim Science Hall serve as warm resting places with cots. A doctor''s clinic works in the Chung-Ang University Hospital building as a stretcher counter, and Heukseok-ro 13-gil ices over first after snow.', '흑석 승강장은 비탈 순번만 부르고, 대머리산 계단은 식량통과 들것이 지나는 한 줄이다. 중앙대학교 서울캠퍼스와 수림과학관은 침상이 놓인 따뜻한 쉼터다. 중앙대학교병원 건물에서는 의사의 진료소가 들것 창구로 일하며, 흑석로13길은 눈 온 뒤 가장 먼저 언다.', 'On opening day, the Heukseok-dong community checks the stretcher counter at the hospital building and whether the campus and slope paths are actually walkable.', '개막일 흑석동 공동체는 병원 건물의 들것 창구와 캠퍼스·사면 길을 실제로 걸을 수 있는지 확인한다.', 1, 1724000.8961817857, 5185.438139735956);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159062000', 312, 'Sadang 1-dong', '사당1동', 'Dongjak-gu', '동작구', 'M621.44,777.95 L619.97,805.49 L620.27,808.33 L613.58,807.37 L606.5,807.5 L593.43,810.16 L588.04,811.73 L587.19,807.2 L599.15,793.56 L600.24,793.63 L602.78,789.74 L603.1,783.32 L613.13,779.39 L620.64,777.77 L621.44,777.95 Z', 'held', '["free-city"]', 'Sadang platform is the southern gate where Gwanak high-density housing and Seocho traffic overlap. The area in front of the Sadang 1-dong shopping street and the convenience store is the waiting area, and on Dongjak-daero escort carts and trade carts fight over the same lane. The Seoul Namsa Elementary School playground is the yard where empty bags are set down.', '사당 승강장은 관악 고밀 주거와 서초 통행이 겹치는 남쪽 개찰이다. 사당1동상점가와 편의점 앞이 대기석이고, 동작대로는 호송 수레와 장사 수레가 같은 차로를 다툰다. 서울남사초 운동장은 빈 가방을 내려놓는 마당이다.', 'On opening day, the Sadang 1-dong Community Center and the fictional guide team check handovers toward Gwanak and Seocho.', '사당1동 주민센터와 창작 안내조는 개막일에 관악·서초 방향 인계를 확인하려 한다.', 1, 632252.8460421563, 10491.53047158876);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159063000', 313, 'Sadang 2-dong', '사당2동', 'Dongjak-gu', '동작구', 'M616.31,699.85 L617.14,711.32 L617.88,713.36 L619.14,715 L633.56,726.78 L635.7,728.26 L638.26,728.35 L637.98,729.7 L633.69,728.44 L629.46,725.9 L625.76,732.11 L624.05,736.4 L623.67,740.4 L623.23,756.05 L621.44,777.95 L620.64,777.77 L613.13,779.39 L611.46,770.85 L609.85,770.82 L606.12,769.64 L603.29,766.2 L597.32,757.85 L594.71,753.1 L594.52,749.16 L593.89,747.35 L581.44,744.77 L575.58,746.27 L572.76,747.44 L566.88,742.54 L561.76,730.91 L564.13,732.18 L577.2,716.14 L583.7,710.4 L591.29,708.3 L592.1,707.78 L598.9,696.73 L616.31,699.85 Z', 'held', '["free-city"]', 'Two Dongjak platform points cut the escort order between the south bank of the Han River and Sadang Pass. The road in front of the Hyeonchungwon National Cemetery sign is a fictional quiet detour and does not claim actual cemetery operations. The foot of Gaetmalsan and the Seoul Dongjak Elementary School playground are the waiting yards.', '동작 승강장 두 점이 한강 남안과 사당 고개 사이 호송 순번을 자른다. 국립현충원 표지 앞 도로는 창작상 조용한 우회로이며 실제 묘역 운영을 주장하지 않는다. 갯말산 기슭과 서울동작초 운동장이 대기 마당이다.', 'On opening day, the Dongjak Station handover team and the Sadang 2-dong guides set zones for actually confirmed foot and supply movement, and do not create a river crossing from the shared Han River boundary alone.', '개막일 동작역 인계조와 사당2동 안내자는 실제 확인된 보행·물자 이동 구획을 정하고 공유 한강 경계만으로 도하를 만들지 않는다.', 2, 2743962.1099059954, 3014.691773671537);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159064000', 314, 'Sadang 3-dong', '사당3동', 'Dongjak-gu', '동작구', 'M603.1,783.32 L599.87,783.28 L586.93,776.77 L578.67,768.49 L576.47,766.18 L567.95,750.76 L564.73,743.98 L566.88,742.54 L572.76,747.44 L575.58,746.27 L581.44,744.77 L593.89,747.35 L594.52,749.16 L594.71,753.1 L597.32,757.85 L603.29,766.2 L606.12,769.64 L609.85,770.82 L611.46,770.85 L613.13,779.39 L603.1,783.32 Z', 'held', '["free-city"]', 'The Chongshin University hill and Dongjak Chunghyo-gil meet at the Sadang gate. Sadang 3-dong Community Center writes gate keys and food turns in one ledger. The Seoul Namseong and Seoul Samil Elementary School yards are empty-basket yards, the stock of Sadang Lotte Castle and Gyeongnam Honorsville competes with hilltop heating, and the planned Hillstate Isu Station Central lot is used only for stacking timber.', '총신대학교 언덕과 동작충효길이 사당 통문으로 모인다. 사당3동주민센터는 통문 열쇠와 식량 순번을 같은 장부에 적는다. 서울남성초·서울삼일초 운동장은 빈 바구니 마당이고, 사당롯데캐슬과 경남아너스빌의 비축은 언덕 난방과 경쟁하며, 힐스테이트이수역센트럴 예정 필지는 각재 적재만 한다.', 'Sadang 3-dong residents'' meeting tries to assign work shifts to keep household food and slope passage around Chongshin University going.', '사당3동 주민 회의는 총신대 주변 가구 식량과 사면 통행을 유지할 작업 교대를 배정하려 한다.', 0, 893687.957825955, 7762.44094960829);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159065000', 315, 'Sadang 4-dong', '사당4동', 'Dongjak-gu', '동작구', 'M603.1,783.32 L602.78,789.74 L600.24,793.63 L599.15,793.56 L587.19,807.2 L583.22,807.08 L580.42,802.96 L577.58,800.11 L573.3,796.55 L578.28,790.08 L582.26,787.79 L585.79,787.4 L589.9,778.96 L589.24,777.85 L599.87,783.28 L603.1,783.32 Z', 'held', '["free-city"]', 'Namseong platform calls only Sadang Market crate turns, and Sadang 4-dong Community Center records scale seats. Samik Greenview, Sadang Humansia, and KCC apartments share the same weak morning power with the market''s ice storage. Hyogan-gong Yi Jeong-yeong''s tomb is a quiet detour at a field edge. The foot of Kkachisan Park is a rest area for carrying firewood.', '남성 승강장은 사당시장 상자 순번만 부르고, 사당4동주민센터는 저울 좌석을 적는다. 삼익그린뷰·사당휴먼시아·KCC 아파트는 시장 얼음 보관과 같은 약한 아침 전력을 나눠 쓴다. 효간공 이정영 묘역은 밭머리의 조용한 우회로이고, 까치산공원 기슭은 땔감을 나르는 쉼터다.', 'On opening day, Sadang Market merchants and the community center try to divide supplies and power for weighing, cold storage, and household heating.', '개막일 사당시장 상인과 주민센터는 계량, 냉장, 가구 난방에 쓸 물자와 전력을 나누려 한다.', 1, 426936.6744105522, 9477.752187924918);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159065100', 316, 'Sadang 5-dong', '사당5동', 'Dongjak-gu', '동작구', 'M589.9,778.96 L585.79,787.4 L582.26,787.79 L578.28,790.08 L573.3,796.55 L570.79,794.19 L561.97,782.37 L562.15,781.16 L564.31,776.07 L564.31,771.63 L564.12,768.68 L561.33,754.85 L561.85,749.7 L564.73,743.98 L567.95,750.76 L576.47,766.18 L585.23,775.2 L586.93,776.77 L589.24,777.85 L589.9,778.96 Z', 'held', '["free-city"]', 'The Sadang Cultural Welfare Center is the alley cauldron, and Kkachisan Park is where dry branches are gathered. Sadang 5-dong Community Center records only cauldron turns. The Seoul Sinnamseong, Sangdo Middle, Dongjak High and Seoul Haengnim Elementary School yards are empty-bowl yards. Sadang Xi and Samho Green Apartments compete with the cauldron fire for the same wood, and Dongjak Chunghyo-gil carries bowls to the welfare center.', '사당문화복지관이 골목 솥이고, 까치산공원은 마른 가지를 모으는 곳이다. 사당5동주민센터는 솥 순번만 적는다. 서울신남성초·상도중·동작고·서울행림초 운동장은 빈 그릇 마당이다. 사당자이와 삼호그린아파트는 솥 불과 같은 땔감을 놓고 협의하고, 동작충효길은 복지관으로 그릇을 나른다.', 'Sadang 5-dong residents, facing the opening-day food shortage, discuss the shifts needed for cooking at the cultural welfare center and for checking walking routes around Kkachisan.', '사당5동 주민들은 개막일 식량 부족에 대응해 문화복지관 취사와 까치산 주변 보행 점검에 필요한 교대를 협의한다.', 0, 661243.9818251227, 6203.307875374838);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159066000', 317, 'Daebang-dong', '대방동', 'Dongjak-gu', '동작구', 'M481.49,665.7 L481.47,670.14 L485.27,675.37 L486.57,684.45 L486.54,690.03 L487.66,697.14 L486.63,698.12 L486.1,699.81 L485.75,700.13 L485.37,702.28 L484.05,703.59 L482.5,703.6 L481.5,702.12 L480.33,702.2 L479.89,705.91 L480.17,707.72 L478.41,708.81 L475.67,709.33 L468.7,709.92 L467.83,710.43 L467.7,711.72 L469.28,719.5 L472.07,720.25 L472.77,720.96 L473.53,723.36 L473.28,724 L469.69,726.03 L468.35,726.45 L464.2,725.1 L462.56,725.1 L450.03,729.93 L447.01,728.97 L444.39,727.58 L446.17,717.2 L459.51,676.77 L462.43,676.46 L464.42,675.55 L464.31,672.2 L458.9,668.67 L461.35,664.37 L478.95,666.08 L481.49,665.7 Z', 'held', '["free-city"]', 'Sindaebang Samgeori platform calls only intersection turns, and the intersection in front of the Naval Club signals the Yeongdeungpo and Daebang carts. The building name is only a survey label for the intersection. Firewood from the foot of Yongmasan and stock at the Seongnam High School and Yeongdeungpo High School yards compete for the same shift. The Dongjak Comprehensive Social Welfare Center is the alley cauldron.', '신대방삼거리 승강장은 교차로 순번만 부르고, 해군회관앞 교차로는 영등포·대방 수레의 신호 지점이다. 건물 이름은 교차로를 가리키는 측량 표지일 뿐이다. 용마산 기슭의 땔감과 성남고·영등포고 운동장 적재가 같은 교대를 놓고 겨룬다. 동작종합사회복지관은 골목 솥이다.', 'On opening day, the Daebang-dong guide team tries to run intersection handovers, schoolyard storage and alley food shares in separate zones.', '개막일 대방동 안내조는 교차로 인계, 학교 마당 적재, 골목 식량 나눔을 서로 다른 구획으로 나누어 운영하려 한다.', 1, 1586539.2536450075, 6316.578664521551);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159067000', 318, 'Sindaebang 1-dong', '신대방1동', 'Dongjak-gu', '동작구', 'M431.95,762.6 L424.09,768.15 L418.1,770.76 L407.48,774.74 L403.18,776 L395.33,775.96 L404.32,761.83 L415.77,745.26 L420.21,736.82 L422.25,735.09 L427.17,734.41 L428.12,747.13 L430.79,756.31 L431.95,762.6 Z', 'held', '["free-city"]', 'Sindaebang platform calls only Dorimcheon embankment turns, and the foot of Waosan is the hill where alley firewood comes from. The frozen Dorimcheon is treated as a hazard, not a path. Seoul Munchang Elementary School and Daebang Middle School playgrounds serve as compost yards, and Boramae Lotte Nakcheondae and Daerim Samgeori compete for the same fuel line.', '신대방 승강장은 도림천 둑 순번만 부르고, 와우산 기슭은 골목 땔감이 나오는 언덕이다. 얼어붙은 도림천은 길이 아니라 위험 지대로 본다. 서울문창초·대방중 운동장은 거름 마당이고, 보라매롯데낙천대와 대림삼거리가 같은 연료선을 놓고 협의한다.', 'Sindaebang 1-dong Community Center, facing the opening-day supply gap, keeps drainage checks around Dorimcheon and household fuel handover as separate jobs and keeps people off the ice.', '신대방1동 주민센터는 개막일 공급 공백 속에서 도림천 주변 배수 점검과 가구 연료 인계를 따로 관리하며 얼음 위로 사람을 올리지 않는다.', 1, 683545.1476920438, 9977.687681681402);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1159068000', 319, 'Sindaebang 2-dong', '신대방2동', 'Dongjak-gu', '동작구', 'M468.35,726.45 L471.62,730.28 L472.86,730.18 L471.52,733.26 L470.6,738.09 L470.57,739.13 L471.93,743.98 L466.88,740.59 L465.8,740.39 L464.77,740.59 L462.56,743.48 L455.88,758.41 L440.35,759.77 L431.95,762.6 L430.79,756.31 L428.12,747.13 L427.17,734.41 L432.31,733.46 L442.81,730.51 L444.26,728.69 L444.39,727.58 L447.01,728.97 L450.03,729.93 L462.56,725.1 L464.2,725.1 L468.35,726.45 Z', 'held', '["free-city"]', 'The Boramae Hospital·Boramae Park stop name is a survey name, and the Seoul Metropolitan Boramae Hospital building is a fictional stretcher handover window. Do not read actual hospital operation from the tag. The Sindaebang 2-dong Community Center records only escort turns. Boramae-ro and the Dorimcheon side are the ice-crate route. The UH-1B marker is merely park debris and does not imply an aircraft formation.', '보라매병원·보라매공원 정거장 이름은 실측이고, 서울특별시 보라매병원 건물은 창작상 들것 인계 창구다. 실제 병원 가동을 태그로 읽지 않는다. 신대방2동주민센터는 호송 순번만 적는다. 보라매로와 도림천 쪽이 얼음 상자 경로다. UH-1B 표지는 공원 잔해일 뿐 항공 편성을 뜻하지 않는다.', 'On opening day, the fictional medical team at the Boramae Hospital building and the community center discuss, amid the contract gap, the shifts needed for stretcher handovers and general household supply transport.', '개막일 보라매병원 건물의 창작 의무조와 주민센터는 계약 공백 속에서 들것 인계와 일반 생활 물자 운반에 필요한 교대를 협의한다.', 2, 1032431.6430072084, 6420.860930502994);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1162052500', 320, 'Boramae-dong', '보라매동', 'Gwanak-gu', '관악구', 'M475.49,746.1 L482.18,747.57 L489.83,749.84 L498.48,752.85 L499.51,755.4 L497.99,760.51 L497.07,764.95 L497.74,766.36 L498.27,766.23 L499.07,765.43 L499.82,765.63 L501.25,766.81 L498.89,772.2 L486.22,771.44 L464.57,760.01 L455.88,758.41 L462.56,743.48 L464.77,740.59 L466.03,740.42 L467.95,741.12 L475.49,746.1 Z', 'held', '["free-city"]', 'The fictional guide team around Danggok Station handles commuter luggage and care-household handovers through the same passage. Work crews demanding fast freight handover and slowly moving residents must divide the time.', '당곡역 주변의 창작 안내조는 출근 짐과 돌봄 가구의 인계를 같은 통로에서 처리한다. 빠른 화물 인계를 요구하는 작업반과 천천히 이동하는 주민이 시간을 나눠야 한다.', 'Boramae-dong residents negotiate the cost of the next choice: separating the care handover time slots.', '보라매동 주민들은 다음 선택의 비용을 협의한다: 돌봄 인계 시간대를 분리한다.', 1, 761601.1937153084, 9014.560450605555);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1162054500', 321, 'Cheongnim-dong', '청림동', 'Gwanak-gu', '관악구', 'M561.87,750.17 L561.33,754.85 L564.12,768.68 L564.31,776.07 L562.36,775.85 L549.27,771.88 L552.37,767.19 L552.64,764.61 L552.39,763.55 L550.05,759.61 L547.12,753.13 L548.86,753.24 L550.75,752.33 L554.51,748.32 L555.31,745.23 L555.82,744.97 L558.98,744.9 L561.76,746.72 L561.87,750.17 Z', 'held', '["free-city"]', 'Residents crossing Bongcheon Pass split and carry the weight of supplies, but when an urgent order comes in, they are tempted to skip safety checks.', '봉천고개를 지나는 주민들은 물자 무게를 나눠 운반하지만 급한 주문이 들어오면 안전 확인을 생략하려 한다.', 'Cheongnim-dong residents negotiate the cost of the next choice: spreading loads before crossing the pass.', '청림동 주민들은 다음 선택의 비용을 협의한다: 고개 통과 전에 짐을 분산한다.', 0, 316304.633720227, 13372.235336081703);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1162056500', 322, 'Seonghyeon-dong', '성현동', 'Gwanak-gu', '관악구', 'M550.05,759.61 L552.39,763.55 L552.64,764.61 L552.48,766.76 L547.56,774.44 L520.77,769.73 L519.48,766.5 L518.48,761.25 L518.4,758.17 L515.2,753.12 L510.66,751.12 L522.18,744.61 L523,745.23 L525.4,745.47 L533.2,750.07 L539.51,754.71 L541.18,755.06 L543.37,754.57 L547.12,753.13 L550.05,759.61 Z', 'held', '["free-city"]', 'The fictional exchange team at the Dong-A Apartment shopping complex tries to change the practice of storing shared parts and personal stock mixed together.', '동아아파트상가의 창작 교환조는 공용 부품과 개인 재고를 섞어 보관해 온 관행을 바꾸려 한다.', 'Seonghyeon-dong residents negotiate the cost of the next choice: separating shared stock from personal orders.', '성현동 주민들은 다음 선택의 비용을 협의한다: 공용 재고와 개인 주문을 분리한다.', 0, 685938.1445695737, 12872.29769900109);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1162057500', 323, 'Haengun-dong', '행운동', 'Gwanak-gu', '관악구', 'M562.15,781.16 L561.97,782.37 L570.79,794.19 L580.42,802.96 L583.22,807.08 L587.19,807.2 L588.04,811.73 L583.42,811.92 L578.69,810.77 L568.45,805.58 L567.96,805.91 L564.62,803.61 L537.32,790.11 L549.27,771.88 L562.36,775.85 L564.31,776.07 L562.15,781.16 Z', 'held', '["free-city"]', 'The fictional production team of Seoul Art High School tries to draw everyday signs that residents who speak different languages can also read.', '서울미술고등학교의 창작 제작조는 서로 다른 언어를 쓰는 주민도 읽을 수 있는 생활 표지를 그리려 한다.', 'Haengun-dong residents negotiate the cost of the next choice: testing signs that residents understand on site.', '행운동 주민들은 다음 선택의 비용을 협의한다: 주민이 이해하는 표지를 현장에서 시험한다.', 1, 723239.4732538584, 11778.671263162492);
