INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1162073500', 337, 'Daehak-dong', '대학동', 'Gwanak-gu', '관악구', 'M538.18,827.06 L539.2,827.86 L546.16,847.85 L545.38,851.2 L544.79,857.54 L545.2,859.17 L550.91,872.12 L552.51,874.65 L562,882.94 L566.97,884.3 L573.95,884.85 L585.32,904.82 L585.66,906.31 L585.34,910.74 L584.61,912.38 L582.31,914.57 L580.62,914.72 L573.32,917.02 L569.99,918.86 L568.77,921.48 L568.29,923.74 L569.07,930.04 L568.15,936.17 L565.89,937.79 L557.15,937.93 L555.04,941.74 L543.55,943.86 L535.94,941.6 L531.43,944.42 L523.39,944 L519.59,945.69 L513.88,949.28 L503.8,947.87 L500.35,953.94 L495.83,952.74 L491.96,944.07 L493.65,937.86 L486.6,928.21 L472.72,919.32 L472.01,915.59 L472.22,911.78 L482.34,902.91 L487.2,896.13 L495.48,878.56 L495.98,875.39 L496.21,869.13 L493.39,861.94 L483.98,848.47 L478.2,844.95 L475.82,845.62 L475.73,843.28 L476.24,840.55 L483.7,823.99 L486.2,825.47 L491.33,826.7 L514.07,830.74 L516.08,832.59 L519.95,830.5 L519.88,821.94 L519.3,820.78 L522.16,821.73 L526.76,821.8 L528.82,822.92 L530.02,824.72 L532.03,826.17 L538.18,827.06 Z', 'held', '["free-city"]', 'The fictional records team remaining in the Multimedia Lecture Building tries to pass repair knowledge to outside work crews while protecting the original equipment and records.', '멀티미디어강의동에 남은 창작 기록조는 수리 지식을 외부 작업반에 전달하되 원본 장비와 기록을 보호하려 한다.', 'Daehak-dong residents negotiate the cost of the next choice: separating field copies from original storage.', '대학동 주민들은 다음 선택의 비용을 협의한다: 현장용 사본과 원본 보관을 분리한다.', 1, 8488326.193997078, 886.5352047052342);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1162074500', 338, 'Samseong-dong', '삼성동', 'Gwanak-gu', '관악구', 'M483.7,823.99 L476.24,840.55 L475.73,843.28 L475.82,845.62 L478.2,844.95 L483.98,848.47 L493.39,861.94 L496.21,869.13 L495.98,875.39 L495.48,878.56 L487.2,896.13 L482.34,902.91 L474.24,910.23 L467.76,901.66 L462.98,896.24 L451.89,886.31 L450.35,882.29 L449.78,878.01 L449.9,876.15 L451.32,874.05 L454.59,867.33 L451.1,855.5 L451.5,853.8 L451.43,850.04 L452.86,846.01 L456.48,842.66 L460.31,837.52 L462.39,819.71 L462.11,814.27 L470.21,812.2 L470.29,813.88 L481.98,819.39 L483.7,823.99 Z', 'held', '["free-city"]', 'Fictional workers around Seoul National University Venture Town jointly repair and lend small electric tools.', '서울대벤처타운 주변의 창작 작업자들은 작은 전기 도구를 공동 수리하고 대여한다.', 'Samseong-dong residents negotiate the cost of the next choice: performing insulation checks before lending.', '삼성동 주민들은 다음 선택의 비용을 협의한다: 대여 전에 절연 점검을 한다.', 1, 2587609.2901910115, 2301.352071417403);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1162076500', 339, 'Miseong-dong', '미성동', 'Gwanak-gu', '관악구', 'M455.24,804.49 L441.81,813.73 L436.87,815.77 L428.79,824.58 L426.68,832.22 L428.91,843.96 L425.06,847.08 L421.31,845.63 L421.21,844.43 L418.98,842.2 L414.75,833.37 L410.55,822.5 L409.39,820.54 L414.15,818.29 L416.57,816.94 L417.18,816.29 L419.24,810.19 L420.13,805.2 L419.25,800.66 L416.46,800.88 L413.12,800.49 L411.24,798.1 L411.25,796.02 L413.87,790.61 L447.9,783 L451.93,798.32 L455.24,804.49 Z', 'held', '["free-city"]', 'The fictional repair team of Seongbo High School tries to mend shared living supplies and personal work clothes together, but materials are limited.', '성보고등학교의 창작 수선조는 공동 생활 물품과 개인 작업복을 함께 수리하려 하지만 재료가 한정돼 있다.', 'Miseong-dong residents negotiate the cost of the next choice: reserving repairs of shared encampment supplies.', '미성동 주민들은 다음 선택의 비용을 협의한다: 공동 숙영 물품 수리를 예약한다.', 0, 1340147.5477450276, 6332.8847739791645);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1162077500', 340, 'Nangok-dong', '난곡동', 'Gwanak-gu', '관악구', 'M462.39,819.71 L460.31,837.52 L456.48,842.66 L452.86,846.01 L451.43,850.04 L451.5,853.8 L440.15,842.52 L428.91,843.96 L426.68,832.22 L427.14,829.84 L428.79,824.58 L436.87,815.77 L441.81,813.73 L455.24,804.49 L462.11,814.27 L462.39,819.71 Z', 'held', '["free-city"]', 'In the yard of Nanu Middle School, the Original Resident Work Crew borrows ladders and carriers from neighboring households and keeps return records.', '난우중학교 마당에서 창작 주민 작업반은 이웃 가구와 사다리·짐받이를 빌려 쓰며 반환 기록을 관리한다.', 'Nangok-dong residents negotiate the cost of the next choice: securing lending time for urgent work.', '난곡동 주민들은 다음 선택의 비용을 협의한다: 긴급 작업용 대여 시간을 확보한다.', 0, 1014139.149183802, 7096.067641005474);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165051000', 341, 'Seocho 1-dong', '서초1동', 'Seocho-gu', '서초구', 'M745.95,793.03 L743.12,793.76 L741.95,794.68 L741.71,798.19 L735.19,804.74 L730.86,807.1 L729.59,807.07 L728.18,800.52 L728.25,795.62 L726.53,789.98 L724.41,787.77 L715.73,769.8 L714.75,765.6 L712.95,751.96 L712.89,747.94 L713.23,746.85 L718.24,744.22 L734.08,738.21 L744.48,773.12 L750.26,794.1 L745.95,793.03 Z', 'held', '["arc"]', 'At the Seoul National University of Education building, the Original Education Team holds classes so residents can read contracts and ration documents themselves. Some households cannot attend because their on-site work hours are long.', '서울교육대학교 건물의 창작 교육조는 주민들이 계약과 배급 문서를 직접 읽도록 수업을 연다. 현장 노동 시간이 길어 수업에 오지 못하는 가구가 생긴다.', 'Seocho 1-dong residents negotiate the cost of the next choice: holding mobile classes scheduled around work shifts.', '서초1동 주민들은 다음 선택의 비용을 협의한다: 작업 교대에 맞춘 이동 수업을 연다.', 1, 1370786.9701888124, 4376.172323241243);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165052000', 342, 'Seocho 2-dong', '서초2동', 'Seocho-gu', '서초구', 'M752.35,731.27 L770.27,778.76 L769.29,781.57 L771.38,786.03 L770.11,788.06 L766.06,792.38 L759.99,795.25 L757.12,794.32 L754.97,792.15 L750.26,794.1 L744.48,773.12 L734.08,738.21 L752.35,731.27 Z', 'held', '["arc"]', 'At the Seocho District Office, the Original Mediation Team tries not to mix supply contracts and new proposals in the same ledger.', '서초구청의 창작 중재조는 공급 계약과 새 제안을 같은 장부에 섞지 않으려 한다.', 'Seocho 2-dong residents negotiate the cost of the next choice: checking contract validity dates against actual deliveries.', '서초2동 주민들은 다음 선택의 비용을 협의한다: 계약 유효일과 실제 납품을 대조한다.', 1, 1233957.6097287824, 6044.453991931992);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165053000', 343, 'Seocho 3-dong', '서초3동', 'Seocho-gu', '서초구', 'M713.23,746.85 L712.89,747.94 L712.95,751.96 L714.75,765.6 L715.73,769.8 L724.41,787.77 L726.53,789.98 L728.25,795.62 L728.18,800.52 L729.59,807.07 L724.53,808.02 L720.99,810.29 L715.67,816.62 L711.63,820.29 L702.19,823.54 L698.74,814.19 L691.78,802.05 L688.28,799.15 L684.5,800.79 L680.44,792.49 L681.29,790.98 L678.98,787.29 L678.23,785.49 L675.21,782.38 L675.23,779.48 L674.54,776.96 L673.67,775.2 L676.29,770.5 L675.24,759.82 L673.76,752.53 L681.37,745.37 L683.39,742.2 L700.79,729.44 L703.36,728.14 L708.83,727.15 L711.91,744.1 L713.59,745.29 L718.24,744.22 L713.23,746.85 Z', 'held', '["arc"]', 'The handover team around Gyodae Station tries not to hold travelers with different purposes of visit for long under the same inspection.', '교대역 주변 인계조는 방문 목적이 다른 통행객을 같은 검사로 오래 붙잡지 않으려 한다.', 'Seocho 3-dong residents negotiate the cost of the next choice: setting up a separate civilian transit zone.', '서초3동 주민들은 다음 선택의 비용을 협의한다: 민간 통행 구획을 별도로 둔다.', 2, 3008516.9174818206, 3203.8044871849197);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165053100', 344, 'Seocho 4-dong', '서초4동', 'Seocho-gu', '서초구', 'M752.35,731.27 L718.24,744.22 L713.49,745.27 L711.91,744.1 L708.64,725.98 L712.17,725.08 L724.34,721 L726.73,713.61 L733.64,711.42 L743.47,707.63 L752.35,731.27 Z', 'held', '["arc"]', 'At Sinnonhyeon Station, the Original Liaison Team collects schedule changes from multiple handover points every shift and posts them.', '신논현역의 창작 연락조는 여러 인계처에서 온 시간 변경을 교대마다 모아 게시한다.', 'Seocho 4-dong residents negotiate the cost of the next choice: separating confirmed schedules from unconfirmed messages.', '서초4동 주민들은 다음 선택의 비용을 협의한다: 확인된 일정과 확인되지 않은 전갈을 구분한다.', 2, 875706.6137422274, 10241.443720145253);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165054000', 345, 'Jamwon-dong', '잠원동', 'Seocho-gu', '서초구', 'M729.19,666.27 L734.45,683.65 L731.7,684.94 L706.63,693.8 L706.76,690.74 L700.23,678.65 L698.09,675.88 L694.39,678.37 L692.78,674.93 L698.95,667.35 L696.75,665.42 L694.92,663.25 L686.23,650.67 L696.47,635.14 L707.7,623.49 L715.49,631.93 L722.53,641.4 L724.05,644.28 L725.95,649.94 L728.03,658.17 L729.3,665 L729.19,666.27 Z', 'held', '["arc"]', 'In winter 2126, Jamwon-dong is a small Arc town on the Han River bank. At its only station, Eastern Rifle Guard members count people and goods going in and out, and the river-side windows have their shutters lowered every night so no light leaks out. There is no factory, so residents with machine bodies mend their joints by reusing old parts.', '2126년 겨울의 잠원동은 한강변에 붙은 아크 영토의 작은 마을이다. 동에 하나뿐인 역에서 동방사 대원이 출입자와 짐을 세고, 강 쪽 창에는 밤마다 덧문을 내려 빛이 밖으로 새지 않게 한다. 공장이 없어서 기계 몸을 쓰는 주민은 낡은 부품을 돌려 쓰며 관절을 고친다.', 'On opening day, Jamwon-dong residents check the shutter latches against the river wind and block the windows that leak light first.', '개막일 잠원동 주민들은 강바람에 덧문 고정쇠가 버티는지 점검하고, 빛이 새는 창부터 먼저 막는다.', 1, 1836480.8991248608, 5649.990699573586);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165055000', 346, 'Banpobon-dong', '반포본동', 'Seocho-gu', '서초구', 'M651.84,688.46 L649.96,694.63 L650.93,700.27 L649.79,703.97 L652.86,712.99 L655.78,713.14 L656.5,714.56 L657.47,718.1 L647.63,725.15 L639.38,728.15 L635.7,728.26 L619.14,715 L617.88,713.36 L617.14,711.32 L616.79,708.81 L616.31,699.85 L618.04,699.59 L632.21,699.44 L646.5,676.5 L651.84,688.46 Z', 'held', '["arc"]', 'Banpo-bondong lies along the frozen Banpocheon, and its Arc station is the only gate for people and goods. Residents split their work between clearing ice from living passages and repairing worn machine-body parts, and the deeper the underground floor, the higher the household''s standing. Anyone who goes out onto the surface after dark is warned about outside machines drawn to light and heat.', '반포본동은 얼어붙은 반포천을 끼고 있으며, 동의 아크 역이 사람과 짐이 드나드는 유일한 문이다. 주민들은 생활 통로의 얼음을 치우는 일과 닳은 기계 몸 부품을 고치는 일에 인력을 나눈다. 지하 깊은 층에 살수록 신분이 높고, 해가 진 뒤 지상에 나가는 사람은 빛과 열에 끌리는 바깥 기계를 조심하라는 주의를 듣는다.', 'On opening day, Banpo-bondong residents clear the ice from the living passages by the stream and mark the spots where passing is unsafe.', '개막일 반포본동 주민들은 천변 생활 통로의 얼음을 걷어 내고 지나기 위험한 구간에 표시를 한다.', 1, 1045714.1909045074, 747.6230186029793);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165056000', 347, 'Banpo 1-dong', '반포1동', 'Seocho-gu', '서초구', 'M743.47,707.63 L733.64,711.42 L726.73,713.61 L724.34,721 L712.17,725.08 L708.64,725.98 L706.34,714.5 L699.4,697.54 L701.26,695.66 L731.7,684.94 L734.64,684.15 L743.47,707.63 Z', 'held', '["arc"]', 'The Original Cooking and Exchange Team spanning the Express Bus Terminal underground mall tries to reduce indoor open flames, but the merchants want to keep their operating hours.', '고속터미널 지하상가에 걸친 창작 취사·교환조는 실내 화기를 줄이려 하지만 상인들은 운영 시간을 유지하려 한다.', 'Banpo 1-dong residents negotiate the cost of the next choice: gathering open-flame work into a separate time slot.', '반포1동 주민들은 다음 선택의 비용을 협의한다: 화기 작업을 분리한 시간대에 모은다.', 3, 1009020.4071944489, 9832.011254940036);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165057000', 348, 'Banpo 2-dong', '반포2동', 'Seocho-gu', '서초구', 'M675.91,704.57 L681.98,714.62 L682.11,715.94 L681.65,716.58 L655.93,729.21 L652.67,729.96 L650.68,730.02 L637.98,729.7 L638.26,728.35 L644.64,726.38 L647.63,725.15 L657.47,718.1 L656.5,714.56 L655.78,713.14 L652.86,712.99 L650.04,705.17 L649.9,703.08 L650.93,700.27 L649.96,694.63 L651.84,688.46 L646.5,676.5 L661.82,666.8 L675.91,704.57 Z', 'held', '["arc"]', 'The Sewage Facility Management Center in Banpo 2-dong is a large building that still holds some warmth. Its inspection team keeps the rooms for machine-body repair and the rooms for storing stock apart, and it covers every vent because escaping heat can draw outside machines. The station on the street counts who goes in and out.', '반포2동의 하수시설물관리센터는 아직 온기가 남은 큰 건물이다. 점검조는 기계 몸을 고치는 방과 비축품을 두는 방을 나누어 관리하고, 새어 나가는 열이 바깥 기계를 끌어들일 수 있어 환기구를 모두 덮어 둔다. 길가 역에서는 드나드는 사람을 센다.', 'On opening day, the inspection team lists which rooms of the facility are warm enough for repairs and which vents are still uncovered.', '개막일 점검조는 시설 안에서 수리에 쓸 만큼 따뜻한 방과 아직 덮지 못한 환기구를 목록으로 만든다.', 1, 1187495.630485557, 6677.329833001385);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165058000', 349, 'Banpo 3-dong', '반포3동', 'Seocho-gu', '서초구', 'M706.63,693.8 L675.91,704.57 L661.82,666.8 L674.6,658.93 L686.23,650.67 L694.92,663.25 L696.75,665.42 L698.95,667.35 L692.78,674.93 L694.39,678.37 L698.09,675.88 L700.23,678.65 L706.76,690.74 L706.63,693.8 Z', 'held', '["arc"]', 'The Original Storage Team of the underground mall spanning several dongs cannot confirm which zone it received items from and suffers return disputes.', '여러 동에 걸친 지하상가의 창작 보관조는 짐을 어느 구획에서 받았는지 확인하지 못해 반환 분쟁을 겪는다.', 'Banpo 3-dong residents negotiate the cost of the next choice: recording the recipient for each zone as well.', '반포3동 주민들은 다음 선택의 비용을 협의한다: 구획별 수령자를 함께 기록한다.', 0, 1308172.5707446507, 5386.674631152684);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165058100', 350, 'Banpo 4-dong', '반포4동', 'Seocho-gu', '서초구', 'M708.83,727.15 L703.36,728.14 L700.79,729.44 L683.39,742.2 L681.37,745.37 L673.76,752.53 L665.13,746.24 L660.02,744.99 L659.66,742.33 L658.46,740.28 L658.87,738.69 L658.3,737.65 L655.24,737.21 L654.76,737.79 L652.86,736.59 L652.85,735.55 L652.34,734.54 L648.01,733.29 L647.06,732.35 L646.46,731.02 L646.47,730.03 L652.67,729.96 L655.93,729.21 L658.33,728.23 L681.65,716.58 L682.11,715.94 L681.98,714.62 L675.91,704.57 L701.26,695.66 L699.4,697.54 L706.34,714.5 L708.83,727.15 Z', 'held', '["arc"]', 'At the Seoul St. Mary''s Hospital building, the Original Medical Team allocates supplies for emergency preparedness and support for nearby camps from the same stock.', '서울성모병원 건물의 창작 의무조는 응급 준비에 쓸 물자와 주변 숙영지 지원을 같은 재고에서 배정한다.', 'Banpo 4-dong residents negotiate the cost of the next choice: setting aside minimum emergency stock first.', '반포4동 주민들은 다음 선택의 비용을 협의한다: 응급용 최소 재고를 먼저 남긴다.', 1, 1457423.3782692337, 3650.0032038166573);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165059000', 351, 'Bangbaebon-dong', '방배본동', 'Seocho-gu', '서초구', 'M646.47,730.03 L646.46,731.02 L647.06,732.35 L648.01,733.29 L652.34,734.54 L652.85,735.55 L652.86,736.59 L654.76,737.79 L655.24,737.21 L658.3,737.65 L658.87,738.69 L658.46,740.28 L659.66,742.33 L660.02,744.99 L650.91,746.61 L631.4,756.13 L623.23,756.05 L623.67,740.4 L624.05,736.4 L625.76,732.11 L629.46,725.9 L633.69,728.44 L637.98,729.7 L646.47,730.03 Z', 'held', '["arc"]', 'At Seorae Elementary School, the Original Education Team explains the wording of ration and repair contracts to residents who speak different languages.', '서래초등학교의 창작 교육조는 서로 다른 언어를 쓰는 주민에게 배급과 수리 계약의 표현을 설명한다.', 'Bangbae-bondong residents negotiate the cost of the next choice: setting aside separate explanation time before contracts.', '방배본동 주민들은 다음 선택의 비용을 협의한다: 계약 전 설명 시간을 따로 둔다.', 0, 659153.9888457155, 8968.769210291075);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165060000', 352, 'Bangbae 1-dong', '방배1동', 'Seocho-gu', '서초구', 'M678.98,787.29 L662.09,791.77 L654.52,794.78 L643.15,772.18 L670.29,761.96 L675.24,759.82 L676.29,770.5 L673.67,775.2 L674.54,776.96 L675.23,779.48 L675.21,782.38 L678.23,785.49 L678.98,787.29 Z', 'held', '["arc"]', 'The Original Guidance Team in front of the Bangbae Jeil Hospital building tries to take treatment requests and simple item pickups at different times.', '방배제일병원 건물 앞의 창작 안내조는 처치 요청과 단순 물품 수령을 다른 시간에 받으려 한다.', 'Bangbae 1-dong residents negotiate the cost of the next choice: separating item pickup times.', '방배1동 주민들은 다음 선택의 비용을 협의한다: 물품 수령 시간을 분리한다.', 2, 697545.2251914879, 7046.8549170422775);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165061000', 353, 'Bangbae 2-dong', '방배2동', 'Seocho-gu', '서초구', 'M654.52,794.78 L644.06,799.13 L636.35,803.89 L634.27,805.67 L632.72,809.69 L631.58,814.7 L632.32,821.33 L634.75,827.06 L641.25,828.97 L652.13,833.12 L657.49,835.69 L661.83,843.28 L662.32,850.17 L664.48,853.3 L663.34,859.6 L639.7,874.05 L636.91,869.48 L636.44,865.85 L638.71,853.39 L638.54,847.45 L636.92,842.35 L634.85,839.06 L628.19,832.2 L624.52,825.61 L622.54,821.28 L620.64,814.33 L619.97,805.49 L621.49,775.86 L643.15,772.18 L654.52,794.78 Z', 'held', '["arc"]', 'The Original Guidance Team of Bangbae 2-dong, home to Namtaeryeong Station and the pass, checks traffic coming in from outside against on-site conditions and agreements.', '남태령역과 고개가 있는 방배2동의 창작 안내조는 외부에서 들어오는 통행을 현장 상태와 협약에 맞춰 확인한다.', 'Bangbae 2-dong residents negotiate the cost of the next choice: guiding people only through passage sections confirmed on site.', '방배2동 주민들은 다음 선택의 비용을 협의한다: 현장 확인된 통과 구간만 안내한다.', 1, 1933043.6208306085, 2698.3871154230324);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165062000', 354, 'Bangbae 3-dong', '방배3동', 'Seocho-gu', '서초구', 'M700.37,825.9 L693.87,829.72 L688.83,831.72 L685.38,834.16 L682.34,841.44 L671.8,841.74 L661.83,843.28 L657.49,835.69 L652.13,833.12 L641.25,828.97 L634.75,827.06 L632.32,821.33 L631.58,814.7 L632.72,809.69 L634.27,805.67 L636.35,803.89 L644.06,799.13 L662.09,791.77 L678.98,787.29 L681.29,790.98 L680.44,792.49 L684.5,800.79 L688.28,799.15 L691.78,802.05 L698.74,814.19 L702.19,823.54 L700.37,825.9 Z', 'held', '["arc"]', 'The Original Care Team at the Mosim Nursing Hospital building wants to visit nearby households, but it also lacks the staff who must remain at the base.', '모심요양병원 건물의 창작 돌봄조는 주변 가구를 방문하려 하지만 거점에 남아야 할 인력도 부족하다.', 'Bangbae 3-dong residents negotiate the cost of the next choice: separating the minimum staff for visits from that for the base.', '방배3동 주민들은 다음 선택의 비용을 협의한다: 방문과 거점의 최소 인원을 분리한다.', 0, 2410450.226759071, 1909.684733954931);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1165062100', 355, 'Bangbae 4-dong', '방배4동', 'Seocho-gu', '서초구', 'M675.24,759.82 L670.29,761.96 L643.15,772.18 L621.49,775.86 L623.23,756.05 L631.4,756.13 L650.91,746.61 L660.02,744.99 L665.13,746.24 L673.76,752.53 L675.24,759.82 Z', 'held', '["arc"]', 'The Original Guidance Team separates transit records in which the labels Isu and Chongsindaeipgu get mixed. They do not automatically merge item pickup counters just because the names are identical or similar.', '이수와 총신대입구 표기가 섞이는 통행 기록을 창작 안내조가 구분한다. 이름만 같거나 비슷하다고 물품 수령 창구를 자동으로 합치지 않는다.', 'Bangbae 4-dong residents negotiate the cost of the next choice: checking the handover place and the recipient together.', '방배4동 주민들은 다음 선택의 비용을 협의한다: 인계 장소와 수령자를 함께 확인한다.', 2, 940830.5046003473, 8189.785473923457);
