INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168058000', 364, 'Samseong 1-dong', '삼성1동', 'Gangnam-gu', '강남구', 'M864.16,649.14 L866.04,652.56 L869.42,680.2 L869.62,687.48 L864.13,688.71 L835.82,699.67 L823.67,671.5 L817.62,656.4 L837.82,651.97 L847.16,647.96 L849.99,646.21 L860.71,632.3 L865.56,634.2 L864.16,649.14 Z', 'held', '["arc"]', 'The Original Repair Team around Bongeunsa Station tries to separate personal tools from shared tools to make return responsibility clear.', '봉은사역 주변의 창작 수리조는 개인 도구와 공동 도구를 분리해 반환 책임을 명확히 하려 한다.', 'Samseong 1-dong residents negotiate the cost of the next choice: checking the return condition together with the next user.', '삼성1동 주민들은 다음 선택의 비용을 협의한다: 반납 상태를 다음 사용자와 함께 확인한다.', 3, 1923584.621972578, 1983.1724356831453);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168059000', 365, 'Samseong 2-dong', '삼성2동', 'Gangnam-gu', '강남구', 'M813.84,708.41 L808.49,709.91 L813.52,707.57 L811.29,701.89 L810.23,700.5 L801.95,693.68 L799.97,691.05 L791.91,662.57 L788.91,663.18 L791.7,661.85 L817.62,656.4 L823.67,671.5 L835.82,699.67 L813.84,708.41 Z', 'held', '["arc"]', 'The Original Handover Team of Samseong 2-dong, to which several station entities are assigned, also records the pickup location so that items are not looked up by name and exit alone.', '여러 역 객체가 배정된 삼성2동의 창작 인계조는 이름과 출입구만으로 짐을 찾지 않도록 수령 장소를 함께 기록한다.', 'Samseong 2-dong residents negotiate the cost of the next choice: writing the pickup location on the handover slip as well.', '삼성2동 주민들은 다음 선택의 비용을 협의한다: 수령 장소를 인계표에 함께 적는다.', 6, 1257570.903438381, 7189.336183972072);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168060000', 366, 'Daechi 1-dong', '대치1동', 'Gangnam-gu', '강남구', 'M860.88,760.21 L841.55,764.89 L838.98,766.18 L835.11,768.69 L831.84,756.6 L826.17,741.37 L825.13,739.89 L824.27,737.71 L823.66,734.9 L832.74,734.34 L847.63,728.46 L860.88,760.21 Z', 'held', '["arc"]', 'The Original Education Team at the community center tries to run a study space together with care, but the guardians'' shifts do not line up.', '주민센터의 창작 교육조는 학습 공간을 돌봄과 함께 운영하려 하지만 보호자 교대가 서로 맞지 않는다.', 'Daechi 1-dong residents negotiate the cost of the next choice: dividing care time according to the guardians'' work schedules.', '대치1동 주민들은 다음 선택의 비용을 협의한다: 보호자 작업표에 맞춰 돌봄 시간을 나눈다.', 3, 807220.8658139863, 8747.791712345563);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168061000', 367, 'Daechi 2-dong', '대치2동', 'Gangnam-gu', '강남구', 'M872.32,701.3 L873.39,706.36 L877.39,711.88 L883.02,716.9 L889.62,720.27 L887.21,723.52 L885.52,728.67 L886.16,733.69 L885.96,736.56 L884.82,742.23 L884.04,743.78 L879.01,749.65 L869.49,756.86 L865.7,758.88 L860.88,760.21 L835.82,699.67 L864.13,688.71 L869.62,687.48 L870.59,688.5 L872.32,701.3 Z', 'held', '["arc"]', 'At the Gangnam District Council building, the Original Mediation Team explains new supply proposals to residents, distinguishing them from contracts.', '강남구의회 건물의 창작 중재조는 새 공급 제안과 계약을 구별해 주민에게 설명한다.', 'Daechi 2-dong residents negotiate the cost of the next choice: posting contract dates and actual deliveries together.', '대치2동 주민들은 다음 선택의 비용을 협의한다: 계약 날짜와 실제 납품을 함께 게시한다.', 2, 2059119.7116561884, 5583.113956377655);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168063000', 368, 'Daechi 4-dong', '대치4동', 'Gangnam-gu', '강남구', 'M832.74,734.34 L823.66,734.9 L813.84,708.41 L835.82,699.67 L847.63,728.46 L832.74,734.34 Z', 'held', '["arc"]', 'The Original Records Team in the Hanlim International Graduate University space tries to lend the remaining design materials to outside repair teams while preserving the originals.', '한림국제대학원대학교 공간의 창작 기록조는 남은 설계 자료를 외부 수리조에게 빌려주되 원본을 보존하려 한다.', 'Daechi 4-dong residents negotiate the cost of the next choice: separating original storage from copy lending.', '대치4동 주민들은 다음 선택의 비용을 협의한다: 원본 보관과 사본 대여를 분리한다.', 0, 702644.2622151361, 7770.646248198143);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168064000', 369, 'Yeoksam 1-dong', '역삼1동', 'Gangnam-gu', '강남구', 'M808.49,709.91 L783.27,719.48 L779.38,721.86 L790.25,751.44 L763.63,761.65 L743.39,707.44 L798.82,687.23 L799.97,691.05 L801.95,693.68 L810.23,700.5 L811.29,701.89 L813.52,707.57 L808.49,709.91 Z', 'held', '["arc"]', 'Residents who use the Gukgiwon building as an Original assembly point want to place both camping and supply storage in its wide interior.', '국기원 건물을 창작 집결지로 쓰는 주민들은 넓은 실내에 숙영과 물자 보관을 동시에 배치하려 한다.', 'Yeoksam 1-dong residents negotiate the cost of the next choice: dividing sleeping areas from supply storage.', '역삼1동 주민들은 다음 선택의 비용을 협의한다: 잠자리와 물자 보관을 나눈다.', 2, 2365063.2179684904, 4356.67001275789);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168065000', 370, 'Yeoksam 2-dong', '역삼2동', 'Gangnam-gu', '강남구', 'M824.27,737.71 L790.25,751.44 L779.38,721.86 L783.27,719.48 L808.49,709.91 L813.84,708.41 L823.66,734.9 L824.27,737.71 Z', 'held', '["arc"]', 'The creative practice team at Yeoksam Middle School teaches basic inspection to residents who want to repair their everyday tools themselves.', '역삼중학교의 창작 실습조는 생활 도구를 직접 고치려는 주민에게 기본 점검을 가르친다.', 'Yeoksam 2-dong residents negotiate the cost of the next choice: opening safety training shifts first.', '역삼2동 주민들은 다음 선택의 비용을 협의한다: 안전 실습 교대를 먼저 연다.', 0, 1122528.6811148655, 9613.384656935776);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168065500', 371, 'Dogok 1-dong', '도곡1동', 'Gangnam-gu', '강남구', 'M770.27,778.76 L763.63,761.65 L806.93,744.71 L815.81,766.08 L802.75,772.84 L803.01,773.3 L799.56,774.73 L791.45,776.08 L770.27,778.76 Z', 'held', '["arc"]', 'The creative medical team in the Gangnam Beodeuro Hospital building plans to send support staff to households that find it hard to reach the hub.', '강남베드로병원 건물의 창작 의무조는 거점까지 오기 어려운 가구에 보조 인력을 보내려 한다.', 'Dogok 1-dong residents negotiate the cost of the next choice: accepting visit requests together with the daily ration tickets.', '도곡1동 주민들은 다음 선택의 비용을 협의한다: 방문 요청을 생활 배급표와 함께 받는다.', 0, 1009553.2534415551, 6180.3574786470745);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168065600', 372, 'Dogok 2-dong', '도곡2동', 'Gangnam-gu', '강남구', 'M835,768.76 L801.42,793.57 L798.79,797.21 L791.45,776.08 L799.56,774.73 L802.04,773.76 L803.01,773.3 L802.75,772.84 L806.96,770.47 L810.59,768.59 L811.66,768.45 L815.81,766.08 L806.93,744.71 L824.27,737.71 L825.13,739.89 L826.17,741.37 L831.84,756.6 L835,768.76 Z', 'held', '["arc"]', 'The storage team around Maebong Station wants to agree with residents on rules for what to do when someone who left luggage does not return.', '매봉역 주변 보관조는 짐을 맡긴 사람이 돌아오지 않을 때의 처리 규칙을 주민과 합의하려 한다.', 'Dogok 2-dong residents negotiate the cost of the next choice: storing unclaimed goods separately.', '도곡2동 주민들은 다음 선택의 비용을 협의한다: 미수령 물품을 별도 보관한다.', 2, 1030686.7205644177, 8961.403902576745);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168066000', 373, 'Gaepo 1-dong', '개포1동', 'Gangnam-gu', '강남구', 'M890.47,787.78 L887.36,794.36 L883.64,798.22 L881.72,801.13 L886.02,810.01 L893.99,814.57 L890.48,818.93 L884.64,822.28 L881.05,815.27 L872.75,815.32 L871.26,818.52 L851.99,822.18 L841.17,810.79 L827.01,792.37 L821.2,778.8 L835,768.76 L835.85,772.77 L839.2,779.01 L858.63,799.81 L874.94,787.55 L889.49,774.27 L891.97,783.26 L890.47,787.78 Z', 'held', '["arc"]', 'Gaepo 1-dong sits along the frozen Yangjaecheon and has no station of its own, so people and goods go through the check at the next dong''s station. The carrier team counts food and spare machine-body parts house by house and keeps them off the stream bank where it is coldest. Because the dong is exposed, residents worry most about strangers who take people away.', '개포1동은 얼어붙은 양재천을 끼고 있으며 자체 역이 없어 이웃 동의 역 검사를 거쳐 사람과 짐이 드나든다. 운반조는 가구별 식량과 기계 몸 예비 부품을 세어 가장 추운 천변에서 떨어진 곳에 둔다. 바깥에 트인 동이라 주민들은 사람을 끌고 가는 외부인을 가장 걱정한다.', 'On opening day, the carrier team moves the household food counts away from the stream bank and re-checks the sealed shutters.', '개막일 운반조는 가구별 식량 재고를 천변에서 안쪽으로 옮기고 닫아 둔 덧문을 다시 확인한다.', 0, 1739864.9099885465, 4567.423570863506);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168067000', 374, 'Gaepo 2-dong', '개포2동', 'Gangnam-gu', '강남구', 'M891.97,783.26 L889.49,774.27 L874.94,787.55 L858.63,799.81 L839.2,779.01 L835.85,772.77 L835,768.76 L838.98,766.18 L841.55,764.89 L865.7,758.88 L869.49,756.86 L879.01,749.65 L880.6,755.71 L881.68,755.84 L888.07,753.16 L887.91,752.76 L891.54,751.28 L894.38,758.51 L896.72,768.3 L895.01,770.97 L891.97,783.26 Z', 'held', '["arc"]', 'The creative care team in the Gaepo Childcare Comprehensive Support Center space jointly manages the schedules of guardians who take part in ration transport.', '개포육아종합지원센터 공간의 창작 돌봄조는 배급 운반에 참여하는 보호자의 일정을 함께 관리한다.', 'Gaepo 2-dong residents negotiate the cost of the next choice: organizing rotating guardian care.', '개포2동 주민들은 다음 선택의 비용을 협의한다: 보호자 순환 돌봄을 편성한다.', 2, 1585372.181546868, 7568.63286719988);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168067500', 375, 'Gaepo 3-dong', '개포3동', 'Gangnam-gu', '강남구', 'M932.51,733.88 L926.73,737.34 L901.33,747.45 L902,750.1 L907.53,765.45 L895.01,770.97 L896.72,768.3 L894.38,758.51 L891.54,751.28 L887.91,752.76 L888.07,753.16 L881.68,755.84 L880.6,755.71 L879.01,749.65 L884.04,743.78 L884.82,742.23 L885.96,736.56 L886.16,733.69 L885.52,728.67 L887.21,723.52 L889.62,720.27 L912.93,727.35 L932.51,733.88 Z', 'held', '["arc"]', 'Gaepo 3-dong is Arc land beside the Tancheon Reclamation Center, and its two stations are the smallest territorial units here. The deeper the underground layer, the higher the class of the people who live there, and the closer to the surface, the lower. In winter the day starts with counting the shutters and stove fuel on the surface levels. The technical team gathers spare parts for machine-body repairs from the center''s compounds and posts signs that remind people of the light taboo, so that outside machines are not drawn by light and heat.', '개포3동은 탄천물재생센터 곁에 자리한 아크의 땅으로, 역 두 곳이 가장 작은 구역 단위를 이룬다. 지하가 깊을수록 윗사람이 살고 지상에 가까울수록 아랫사람이 산다. 겨울에는 지상 층의 셔터와 난로 연료를 세는 일이 하루의 시작이다. 기술조는 기계 몸 수리에 쓸 부품을 센터 구획에서 모아 오고, 밖의 기계가 빛과 열에 끌려오지 않도록 불빛 금기를 알리는 표지를 붙인다.', 'On opening morning, the Eastern Rifle Guard patrol at the Gaepo 3-dong station entrances checks that the shutters are down and the night lights are covered. The technical team carries boxes of machine-body repair parts down from the frozen surface passage to the underground levels.', '개막일 아침, 개포3동 역 입구에서는 동방사 순찰이 셔터가 내려졌는지, 야간 불빛이 가려졌는지 확인한다. 기술조는 얼어붙은 지상 통로에서 기계 몸 수리 부품 상자를 지하 층으로 옮긴다.', 2, 1033187.9004038307, 4484.082709630252);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168069000', 376, 'Gaepo 4-dong', '개포4동', 'Gangnam-gu', '강남구', 'M851.99,822.18 L850.88,833.68 L849.29,836.15 L833.77,838.14 L828.96,837.61 L816.2,831.89 L814.8,830.48 L819.06,826.89 L801.87,805.95 L798.79,797.21 L801.42,793.57 L821.2,778.8 L827.01,792.37 L841.17,810.79 L851.99,822.18 Z', 'held', '["arc"]', 'The creative walking-inspection team around Guksubong posts separately the paths that are visible and the passages that have been confirmed on site.', '국수봉 주변 창작 보행 점검조는 시야에 보이는 길과 현장으로 확인한 통로를 나누어 게시한다.', 'Gaepo 4-dong residents negotiate the cost of the next choice: guiding people only along walking sections that have been inspected.', '개포4동 주민들은 다음 선택의 비용을 협의한다: 점검한 보행 구간만 안내한다.', 0, 1582401.773830958, 4349.274699900084);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168070000', 377, 'Segok-dong', '세곡동', 'Gangnam-gu', '강남구', 'M991.42,786.61 L993.15,788.25 L1018.34,831.77 L1021.11,837.4 L1023.01,842.09 L1023.68,848.06 L1023.3,850.38 L1022.01,851.05 L1009.39,861.28 L1008.58,862.53 L1008.03,864.56 L1007.29,874.15 L1004,874.13 L998.4,869.99 L997.27,868.92 L996.22,867.3 L997.63,866.07 L997.72,865.19 L993.77,863.42 L977.4,859.83 L972.88,861.21 L972.14,865.27 L970.62,868.55 L969.31,870.28 L960.85,872.31 L954.13,873.21 L950.22,870.26 L947.82,859.84 L945.03,855.66 L942.22,854.46 L940.29,852.98 L927.16,839.69 L919.87,831.41 L916.99,827.09 L914.98,822.36 L916.94,813.73 L918.08,812.74 L921.33,811.02 L936.42,806.25 L939.43,806.67 L947.37,805.48 L951.92,803.77 L952.32,799.84 L952.19,797.12 L951.8,795.53 L952.96,790.37 L953.82,788.95 L958.17,785.42 L967.16,779.15 L971.08,779.74 L973.83,784.63 L975.68,787.1 L979.51,786.88 L983.38,785.88 L988.39,785.54 L991.42,786.61 Z', 'held', '["arc"]', 'The creative ration team at Yulhyeon Elementary School debates whether to receive the goods of widely scattered households all at once or to split them among nearby handover points.', '율현초등학교의 창작 배급조는 넓게 떨어진 가구들의 물품을 한 번에 받을지 가까운 인계처로 나눌지 고민한다.', 'Segok-dong residents negotiate the cost of the next choice: setting aside reserved handovers for each household.', '세곡동 주민들은 다음 선택의 비용을 협의한다: 가구별 예약 인계를 나누어 둔다.', 0, 5908165.37058401, 2318.740106397163);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168072000', 378, 'Ilwonbon-dong', '일원본동', 'Gangnam-gu', '강남구', 'M936.42,806.25 L921.33,811.02 L918.08,812.74 L916.94,813.73 L913.24,813.09 L905.07,814.05 L903.14,815.06 L897.35,815.14 L893.99,814.57 L886.02,810.01 L881.72,801.13 L883.64,798.22 L887.36,794.36 L890.47,787.78 L891.97,783.26 L895.01,770.97 L907.53,765.45 L933.21,755.98 L934.82,759.81 L942.97,770.89 L945.3,786.65 L945.03,788.2 L942.94,791.37 L939.79,798.5 L939.43,806.67 L936.42,806.25 Z', 'held', '["arc"]', 'The creative medical team in the Samseong Seoul Hospital building decides whether to prioritize preparing for current treatment needs over increasing reserves.', '삼성서울병원 건물의 창작 의무조는 비축을 늘리는 일보다 현재 필요한 처치 준비를 우선할지 결정한다.', 'Ilwonbon-dong residents negotiate the cost of the next choice: allocating stock for same-day treatment first.', '일원본동 주민들은 다음 선택의 비용을 협의한다: 당일 처치용 재고를 우선 배정한다.', 1, 2424241.767820162, 2754.1807457610416);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168073000', 379, 'Ilwon 1-dong', '일원1동', 'Gangnam-gu', '강남구', 'M965.42,747.83 L957.53,750.76 L954.86,751.47 L937.6,754.45 L907.53,765.45 L902,750.1 L901.33,747.45 L926.73,737.34 L932.51,733.88 L950.47,739.87 L965.42,747.83 Z', 'held', '["arc"]', 'Ilwon 1-dong is Arc land with no station of its own, adjoining the other compounds of the Tancheon Reclamation Center. It depends on the station of a neighboring dong, which counts the food and fuel it receives. The empty compounds are a gap where winter wind and outside machines can slip in. Residents of the low surface levels follow a rule to put out lights and lower the shutters at dusk.', '일원1동은 자체 역이 없는 아크의 땅으로, 탄천물재생센터의 다른 시설 구획과 맞닿아 있다. 식량과 연료는 이웃 동 역이 세어서 내어 준다. 비어 있는 시설 구획은 겨울바람과 밖의 기계가 스며드는 틈이다. 낮은 지상 층 주민들은 해가 지면 불을 끄고 셔터를 내리는 규칙을 지킨다.', 'On opening day, a few Ilwon 1-dong residents walk the passages between the compounds, checking for broken shutters and places where light leaks out. Rumors that a band looking to snatch people has passed through have led parents to move their children to levels closer to the underground.', '개막일 일원1동에서는 주민 몇이 시설 구획 사이 통로를 돌며 부서진 셔터와 불빛이 새는 곳을 점검한다. 사람을 끌고 가려는 무리가 지나갔다는 소문 때문에 부모들은 아이들을 지하에 더 가까운 층으로 옮긴다.', 0, 945478.5989144992, 4437.752483046347);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1168075000', 380, 'Suseo-dong', '수서동', 'Gangnam-gu', '강남구', 'M988.91,772.26 L992.8,780.63 L994.83,784.31 L993.29,785.59 L991.27,786.46 L988.39,785.54 L983.38,785.88 L979.51,786.88 L975.68,787.1 L973.83,784.63 L971.08,779.74 L967.16,779.15 L958.17,785.42 L953.82,788.95 L952.96,790.37 L951.8,795.53 L952.19,797.12 L952.32,799.84 L951.92,803.77 L947.37,805.48 L939.43,806.67 L939.79,798.5 L942.94,791.37 L945.03,788.2 L945.3,786.65 L942.97,770.89 L934.82,759.81 L933.21,755.98 L937.6,754.45 L954.86,751.47 L957.53,750.76 L965.42,747.83 L970.23,751.11 L976.04,755.88 L983.06,763.48 L988.91,772.26 Z', 'held', '["arc"]', 'The creative handover team, which does not assume that the multiple source-data objects at Suseo Station equal the number of physical facilities, records the passage purpose and the recipient of each zone together.', '수서역의 여러 원자료 객체를 한 물리 시설 수로 단정하지 않는 창작 인계조는 통행 목적과 구획별 수령자를 함께 기록한다.', 'Suseo-dong residents negotiate the cost of the next choice: recording the zone, the recipient, and the handover time together.', '수서동 주민들은 다음 선택의 비용을 협의한다: 구획·수령자·인계 시각을 함께 기록한다.', 4, 1622896.9920039577, 2477.606416064017);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171051000', 381, 'Pungnap 1-dong', '풍납1동', 'Songpa-gu', '송파구', 'M1026.99,586.49 L1021.32,605.98 L991.77,595.31 L972.35,595.36 L987.95,568.54 L1013.52,577.79 L1016.42,579.48 L1022.41,584.21 L1026.99,586.49 Z', 'held', '["arc"]', 'Pungnap 1-dong faces the Han River in the cold and has no station of its own. Its distribution team counts household food and fuel and keeps the stock in higher, inner storage rooms away from the river wind. Shutters are lowered at dusk, and families fear kidnappers who might slip in from the riverside.', '풍납1동은 추운 한강 쪽으로 트여 있고 자체 역이 없다. 배급조는 가구의 식량과 연료를 세어 강바람이 닿지 않는 안쪽 높은 보관실에 둔다. 해 질 녘에 덧문을 내리며, 가족들은 강변에서 숨어드는 납치범을 두려워한다.', 'On opening day, the distribution team moves the most needed food into the inner storage room and still delivers to households that cannot walk far.', '개막일 배급조는 꼭 필요한 식량을 안쪽 보관실로 옮기면서 멀리 걷지 못하는 가구에도 배달을 이어 간다.', 0, 1057035.3810599493, 2982.3032005219256);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171052000', 382, 'Pungnap 2-dong', '풍납2동', 'Songpa-gu', '송파구', 'M1019.74,612.42 L1015.23,624.11 L1007.27,638.84 L977.9,638.94 L972.69,637.77 L957.32,624.27 L969.58,600.16 L972.35,595.36 L991.77,595.31 L995.54,596.62 L1021.32,605.98 L1019.74,612.42 Z', 'held', '["arc"]', 'Residents who use Pungnap Middle School as a creative evacuation assembly point create a handover roster so that families and care households are not separated.', '풍납중학교를 창작 대피 집결지로 쓰는 주민들은 가족과 돌봄 가구가 흩어지지 않게 인계 명단을 만든다.', 'Pungnap 2-dong residents negotiate the cost of the next choice: confirming the handover of people first.', '풍납2동 주민들은 다음 선택의 비용을 협의한다: 사람 인계를 먼저 확인한다.', 0, 1991366.6273681568, 3468.8740411048934);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171053100', 383, 'Geoyeo 1-dong', '거여1동', 'Songpa-gu', '송파구', 'M1093.41,732.71 L1082.21,764.55 L1081.76,764.38 L1081.23,763.47 L1081.54,761.2 L1081.27,758.05 L1080.45,757.64 L1079.69,755.43 L1078.74,755.33 L1068.02,759.79 L1064.88,764.38 L1062.48,763.04 L1062.67,760.49 L1066.65,756.05 L1066.77,750.18 L1068.3,748.24 L1068.65,745.85 L1072.43,740.99 L1073.96,741.99 L1076.7,734.73 L1080.22,727.44 L1093.41,732.71 Z', 'held', '["arc"]', 'The creative technical team in the Seoul Artificial Intelligence High School workspace wants to repair the remaining electronic equipment into everyday communication tools.', '서울인공지능고등학교 작업 공간의 창작 기술조는 남은 전자 장비를 생활 연락 도구로 고치려 한다.', 'Geoyeo 1-dong residents negotiate the cost of the next choice: inspecting the shared charging equipment first.', '거여1동 주민들은 다음 선택의 비용을 협의한다: 공용 충전 장비를 먼저 검사한다.', 1, 505887.364953463, 6980.40758603419);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171053200', 384, 'Geoyeo 2-dong', '거여2동', 'Songpa-gu', '송파구', 'M1104.1,742.18 L1107.5,746.28 L1110.31,750.82 L1106.91,751.84 L1104.08,754.09 L1104.53,755.73 L1105,756.3 L1102.12,759.75 L1098.57,761.26 L1095.35,764.99 L1095.06,767.92 L1093.6,771.04 L1091.57,771.24 L1090.79,771.87 L1088.99,770.68 L1087.53,770.68 L1086.49,768.04 L1086.84,766.94 L1083.76,765.86 L1083.13,765.07 L1082.21,764.55 L1093.41,732.71 L1104.1,742.18 Z', 'held', '["arc"]', 'The creative cooking team at Geowon Elementary School prepares meals by pooling each household''s grain, but every shift returns at a different time.', '거원초등학교의 창작 취사조는 가구별 곡물을 모아 식사를 준비하지만 교대마다 돌아오는 시간이 다르다.', 'Geoyeo 2-dong residents negotiate the cost of the next choice: setting aside meals separately for shifts that return late.', '거여2동 주민들은 다음 선택의 비용을 협의한다: 귀환이 늦은 교대의 식사를 따로 남긴다.', 0, 505583.5422925281, 13569.27080516123);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171054000', 385, 'Macheon 1-dong', '마천1동', 'Songpa-gu', '송파구', 'M1132,745.03 L1131.1,748.6 L1127.26,759.06 L1126.63,759.91 L1125.13,760.95 L1121.43,758.17 L1110.31,750.82 L1105.82,744.09 L1104.1,742.18 L1100.24,738.84 L1122.88,731.35 L1132.15,735.8 L1132,745.03 Z', 'held', '["arc"]', 'The creative porters around Macheon Station want to fix the broken wheels of the handcarts together, but they are also short of replacement parts.', '마천역 주변 창작 짐꾼들은 손수레의 고장 난 바퀴를 함께 고치려 하지만 교환할 부품도 부족하다.', 'Macheon 1-dong residents negotiate the cost of the next choice: repairing the shared ration carts first.', '마천1동 주민들은 다음 선택의 비용을 협의한다: 공용 배급 수레부터 수리한다.', 1, 519155.1653365039, 8677.752434727106);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171055000', 386, 'Macheon 2-dong', '마천2동', 'Songpa-gu', '송파구', 'M1122.88,731.35 L1100.24,738.84 L1093.41,732.71 L1080.22,727.44 L1087.17,709.62 L1089.63,712.82 L1091.97,713.3 L1096.65,713.68 L1103.65,709.24 L1105.71,710.71 L1108.74,714.16 L1110.83,714.27 L1112.49,715.6 L1114.64,715.6 L1121.82,718.7 L1125.12,714.44 L1125.84,714.72 L1133.51,721.46 L1135.87,724.69 L1135.86,726.99 L1133.5,733.88 L1132.15,735.8 L1122.88,731.35 Z', 'held', '["arc"]', 'The merchants of Macheon Market want to collect empty boxes jointly and use them for ration transport, but there is no one in charge of returns.', '마천시장 상인들은 빈 상자를 공동 회수해 배급 운반에 쓰려 하지만 반환 담당자가 없다.', 'Macheon 2-dong residents negotiate the cost of the next choice: opening a shared box return desk.', '마천2동 주민들은 다음 선택의 비용을 협의한다: 공동 상자 반환대를 연다.', 0, 957322.446550262, 5264.997199389674);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171056100', 387, 'Bangi 1-dong', '방이1동', 'Songpa-gu', '송파구', 'M1028.5,705.85 L1024.28,705.82 L1007.76,697.17 L1020.38,672.64 L1040.3,682.99 L1028.5,705.85 Z', 'held', '["arc"]', 'The creative practice team at Bangsan High School wants to continue everyday repair training, but classes are often interrupted by emergency site assignments.', '방산고등학교의 창작 실습조는 생활 수리 교육을 이어가려 하지만 긴급 현장 차출로 수업이 자주 끊긴다.', 'Bangi 1-dong residents negotiate the cost of the next choice: recording apprenticeship practice hours on the work chart.', '방이1동 주민들은 다음 선택의 비용을 협의한다: 도제 실습 시간을 작업표에 남긴다.', 0, 585039.3102617103, 7540.518940559);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171056200', 388, 'Bangi 2-dong', '방이2동', 'Songpa-gu', '송파구', 'M1020.38,672.64 L1007.76,697.17 L995.14,687.75 L983.26,681.9 L979.18,669.14 L996.72,661.27 L996.13,662.01 L1014.66,670.68 L1020.38,672.64 Z', 'held', '["arc"]', 'The creative liaison team at Songpa Naru Station wants to relay ration schedule changes to households, but conflicting notices are still posted.', '송파나루역 창작 연락조는 배급 일정 변경을 가구에게 전달하려 하지만 서로 다른 게시가 남아 있다.', 'Bangi 2-dong residents negotiate the cost of the next choice: updating the ration timetable within the same shift.', '방이2동 주민들은 다음 선택의 비용을 협의한다: 배급 시간표를 같은 교대에 갱신한다.', 1, 766981.2011249955, 10318.766598700768);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171056600', 389, 'Olyun-dong', '오륜동', 'Songpa-gu', '송파구', 'M1015.23,624.11 L1084,662.61 L1088.03,664.37 L1090.3,666.08 L1090.27,667.49 L1088.15,669.45 L1078.03,669.06 L1084.19,675.08 L1084.85,679.73 L1080.66,679.35 L1077.97,681.02 L1075.41,689.98 L1074.61,694.43 L1075.34,695.15 L1064.26,695.2 L1020.38,672.64 L1014.66,670.68 L996.13,662.01 L996.72,661.27 L1007.27,638.84 L1015.23,624.11 Z', 'held', '["arc"]', 'Oryun-dong has three stations around Olympic Park Station, and the wide open space there is used as a waiting area where arrivals are counted. Meals and winter clothing are shared out in turns, and the Eastern Rifle Guard watches the crowd. People are kept in the lower floors at night, with the lights out, so the open ground does not draw outside machines.', '오륜동에는 올림픽공원역 주변에 역이 세 곳 있고, 넓은 빈터를 도착한 사람을 세는 대기 공간으로 쓴다. 식사와 겨울 옷은 차례로 나눠 주고 동방사가 인파를 지켜본다. 밤에는 불을 끄고 사람들을 아래층에 머물게 해서 열린 터가 바깥 기계를 끌지 않게 한다.', 'On opening day, Oryun-dong residents set the waiting turns by the number of meals available and keep the new arrivals indoors after dark.', '개막일 오륜동 주민들은 준비된 식사 수에 맞춰 대기 순번을 나누고 새로 온 사람들을 해 진 뒤에는 실내에 머물게 한다.', 3, 3135742.6528728935, 1660.2765521048743);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171057000', 390, 'Ogeum-dong', '오금동', 'Songpa-gu', '송파구', 'M1078.34,700.39 L1077.33,704.85 L1077.9,705.75 L1084.84,709.38 L1087.17,709.62 L1080.22,727.44 L1076.7,734.73 L1073.96,741.99 L1060.15,733.16 L1052.06,726.98 L1047.84,724.15 L1040.58,718.04 L1028.5,705.85 L1040.3,682.99 L1064.26,695.2 L1075.34,695.15 L1078.34,700.39 Z', 'held', '["arc"]', 'The creative ration team around Garong Station coordinates the tickets so that households do not receive goods twice at different handover points.', '개롱역 주변 창작 배급조는 가구가 여러 인계처에서 중복 수령하지 않도록 표를 맞춘다.', 'Ogeum-dong residents negotiate the cost of the next choice: separating temporary receipt from after-the-fact verification.', '오금동 주민들은 다음 선택의 비용을 협의한다: 임시 수령과 사후 확인을 분리한다.', 2, 1732293.7812449948, 6391.929659899882);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171058000', 391, 'Songpa 1-dong', '송파1동', 'Songpa-gu', '송파구', 'M1003.33,705.94 L1000.45,710.37 L997.73,713.17 L994.28,715.56 L989,717.86 L976.32,701.56 L971.56,693.46 L983.26,681.9 L995.14,687.75 L1007.76,697.17 L1003.33,705.94 Z', 'held', '["arc"]', 'The creative care team in the Songpa Women''s Cultural Center space runs a place where children and frail elders can stay while guardians go out on transport work. The care choice for Songpa 1-dong is not adding more shift staff but coordinating guardian handover times with ration waiting times.', '송파여성문화회관 공간의 창작 돌봄조는 보호자가 운반 일을 나가는 동안 아이와 노약자의 머무를 자리를 운영한다. 송파1동의 돌봄 선택은 교대 인력을 더 넣는 것보다 보호자 인계 시각을 배급 대기와 조정하는 일이다.', 'Songpa 1-dong residents negotiate the cost of the next choice: organizing rotating guardian care.', '송파1동 주민들은 다음 선택의 비용을 협의한다: 보호자 순환 돌봄을 편성한다.', 1, 696204.2449233566, 9831.597623702406);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171059000', 392, 'Songpa 2-dong', '송파2동', 'Songpa-gu', '송파구', 'M1022.02,716.97 L1016.77,721.87 L1012.84,724.86 L1002.27,731.54 L993.21,723.62 L989,717.86 L994.28,715.56 L996.08,714.46 L999.53,711.52 L1002.26,707.93 L1007.76,697.17 L1024.28,705.82 L1022.02,716.97 Z', 'held', '["arc"]', 'The creative repair team in the Garak High School yard divides reclaimed timber between roof repairs and transport boxes.', '가락고등학교 마당의 창작 수리조는 회수 목재를 지붕 보수와 운반 상자에 나누어 쓴다.', 'Songpa 2-dong residents negotiate the cost of the next choice: inspecting the roof-support members first.', '송파2동 주민들은 다음 선택의 비용을 협의한다: 지붕 받침용 부재부터 검사한다.', 0, 598815.2459841911, 8461.708405022424);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171060000', 393, 'Seokchon-dong', '석촌동', 'Songpa-gu', '송파구', 'M993.21,723.62 L990.25,724.78 L987.52,721.43 L953.01,734.14 L952.22,735.88 L949.98,734.89 L952.28,701.33 L955.57,701.64 L959.63,700.79 L967.59,696.58 L971.56,693.46 L976.32,701.56 L993.21,723.62 Z', 'held', '["arc"]', 'The creative repairers at the place marked as the Hyundai Repair Center want to adapt the remaining equipment to everyday carts.', 'Hyundai Repair Center로 표시된 장소의 창작 수리공들은 남은 장비를 생활 수레에 맞춰 사용하려 한다.', 'Seokchon-dong residents negotiate the cost of the next choice: checking the specifications of shared cart parts.', '석촌동 주민들은 다음 선택의 비용을 협의한다: 공용 수레 부품의 규격을 확인한다.', 0, 931733.1521578409, 9624.644115358082);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171061000', 394, 'Samjeon-dong', '삼전동', 'Songpa-gu', '송파구', 'M952.28,701.33 L949.98,734.89 L952.22,735.88 L950.47,739.87 L912.93,727.35 L933.39,697.68 L952.28,701.33 Z', 'held', '["arc"]', 'The creative medical team in the Gangnamsu Hospital building assigns visits to nearby households together with support for treatment at the hub.', '강남수병원 건물의 창작 의무조는 주변 가구 방문과 거점 처치 지원을 함께 배정한다.', 'Samjeon-dong residents negotiate the cost of the next choice: accepting visit requests together with the ration handover.', '삼전동 주민들은 다음 선택의 비용을 협의한다: 방문 요청을 배급 인계 때 함께 받는다.', 1, 989760.1748264461, 8517.820997877896);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171062000', 395, 'Garak-bondong', '가락본동', 'Songpa-gu', '송파구', 'M1040.58,718.04 L1036.28,724.12 L1026.75,743.27 L1035.04,755.77 L1020.17,764.76 L1007.6,743.74 L1001.78,735.03 L1002.27,731.54 L1012.84,724.86 L1016.77,721.87 L1022.02,716.97 L1024.28,705.82 L1028.5,705.85 L1040.58,718.04 Z', 'held', '["arc"]', 'The creative medical team in the building marked as the National Police Hospital wants to distribute treatment-preparation supplies regardless of affiliation.', '국립 경찰병원으로 표시된 건물의 창작 의무조는 소속을 따지지 않고 처치 준비 물자를 배분하려 한다.', 'Garakbon-dong residents negotiate the cost of the next choice: allocating supplies according to urgency.', '가락본동 주민들은 다음 선택의 비용을 협의한다: 긴급도 기준으로 물자를 배정한다.', 1, 1048942.26537004, 7021.644797010549);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171063100', 396, 'Garak 1-dong', '가락1동', 'Songpa-gu', '송파구', 'M1002.27,731.54 L1001.78,735.03 L1007.6,743.74 L1012.63,752.06 L983.06,763.48 L976.04,755.88 L970.23,751.11 L966.15,748.21 L950.47,739.87 L953.01,734.14 L987.52,721.43 L990.25,724.78 L993.21,723.62 L1002.27,731.54 Z', 'held', '["arc"]', 'The creative merchants and ration team of the Garak Agricultural and Marine Products Wholesale Market want to allocate the remaining refrigeration power first to perishable goods. The market itself does not produce food.', '가락농수산물종합도매시장의 창작 상인과 배급조는 남은 냉장 전력을 부패하기 쉬운 물건에 우선 배정하려 한다. 시장 자체가 식량을 생산하지는 않는다.', 'Garak 1-dong residents negotiate the cost of the next choice: disclosing the refrigeration hours and stock.', '가락1동 주민들은 다음 선택의 비용을 협의한다: 냉장 가능한 시간과 재고를 공개한다.', 1, 1366951.5365969823, 5947.760240454708);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171063200', 397, 'Garak 2-dong', '가락2동', 'Songpa-gu', '송파구', 'M1068.65,745.85 L1055.95,759.38 L1045.53,749.88 L1044.69,749.65 L1035.04,755.77 L1026.75,743.27 L1036.28,724.12 L1040.58,718.04 L1047.84,724.15 L1052.06,726.98 L1060.15,733.16 L1072.43,740.99 L1068.65,745.85 Z', 'held', '["arc"]', 'The creative handover team, which does not count the multiple source-data objects at Police Hospital Station as separate stations, records the actual entrances and the recipients of the luggage together.', '경찰병원역의 여러 원자료 객체를 별도 역 수로 세지 않는 창작 인계조는 실제 출입구와 짐 수령자를 함께 적는다.', 'Garak 2-dong residents negotiate the cost of the next choice: marking on-site zones on the handover chart.', '가락2동 주민들은 다음 선택의 비용을 협의한다: 현장 구획을 인계표에 표시한다.', 6, 940960.2393080126, 8886.241576104392);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171064100', 398, 'Munjeong 1-dong', '문정1동', 'Songpa-gu', '송파구', 'M1045.17,771.17 L1035.32,787.1 L1028.92,788.67 L1020.17,764.76 L1044.69,749.65 L1045.53,749.88 L1055.95,759.38 L1045.17,771.17 Z', 'held', '["arc"]', 'The creative mending team at Munjeong High School repairs work clothes and shared bedding with the same materials and decides the priorities with residents. The storage choice for Munjeong 2-dong is distinguished by reducing the piling up of packaging materials, fuel, and daily goods in the same zone.', '문정고등학교의 창작 수선조는 작업복과 공동 침구를 같은 재료로 고치며 우선순위를 주민과 정한다. 문정2동의 보관 선택은 포장재·연료·생활품이 같은 구획에 쌓이는 일을 줄이는 것으로 구별된다.', 'Munjeong 1-dong residents negotiate the cost of the next choice: reserving time for repairing shared bedding.', '문정1동 주민들은 다음 선택의 비용을 협의한다: 공동 침구 수리 시간을 예약한다.', 0, 667295.1999935389, 8802.700813758102);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171064200', 399, 'Munjeong 2-dong', '문정2동', 'Songpa-gu', '송파구', 'M1028.92,788.67 L1032.25,795.81 L1037.04,811.82 L1035.67,837.34 L1033.34,836.06 L1031.31,837.14 L1027.71,846.5 L1023.3,850.38 L1023.68,848.06 L1023.01,842.09 L1021.11,837.4 L1015.68,827.07 L993.15,788.25 L991.27,786.46 L993.29,785.59 L994.83,784.31 L992.8,780.63 L988.91,772.26 L983.06,763.48 L1012.63,752.06 L1020.17,764.76 L1028.92,788.67 Z', 'held', '["arc"]', 'The creative storage team at Garden Five Life wants to divide the zones so that daily goods and large shipping freight are not piled in the same corridor.', '가든파이브 라이프의 창작 보관조는 생활품과 큰 출하 화물을 같은 복도에 쌓지 않도록 구획을 나누려 한다.', 'Munjeong 2-dong residents negotiate the cost of the next choice: clearing the passage corridors and setting the storage zones.', '문정2동 주민들은 다음 선택의 비용을 협의한다: 통행 복도를 비우고 보관 구획을 정한다.', 1, 2355412.8263064646, 3635.0315767899247);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171064600', 400, 'Jangji-dong', '장지동', 'Songpa-gu', '송파구', 'M1060.97,792.21 L1065.26,792 L1067.69,791.34 L1071.64,791.2 L1069.42,795.62 L1067.37,797.77 L1065.26,799.25 L1060.3,801.05 L1056.14,803.55 L1046.61,812.39 L1036.62,820.59 L1037.04,811.82 L1032.25,795.81 L1028.92,788.67 L1035.32,787.1 L1045.17,771.17 L1068.65,745.85 L1068.3,748.24 L1066.77,750.18 L1066.65,756.05 L1062.67,760.49 L1062.48,763.04 L1064.88,764.38 L1060.97,792.21 Z', 'held', '["arc"]', 'Jangji Station''s fictional guidance team reduces congestion by splitting handover times between households arriving from outside and existing residents.', '장지역의 창작 안내조는 외부에서 도착한 가구와 기존 주민의 인계 시간을 나누어 혼잡을 줄인다.', 'Jangji-dong residents negotiate the cost of the next choice: issuing temporary arrival records first.', '장지동 주민들은 다음 선택의 비용을 협의한다: 임시 도착 기록을 먼저 발급한다.', 1, 1220504.9128335784, 7550.235892623992);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171064700', 401, 'Wirye-dong', '위례동', 'Songpa-gu', '송파구', 'M1124.03,762.88 L1125,764.64 L1109.51,775.01 L1108.69,773.81 L1102.59,778.49 L1099.42,783.11 L1096.46,791.14 L1095.48,807.45 L1086.43,807.03 L1086.26,809.79 L1084.38,814.51 L1084.1,818.62 L1066.05,817.69 L1052.97,815.83 L1052.05,832.26 L1050.82,834.22 L1053.12,839.63 L1047.06,841.79 L1045.07,840.77 L1041.8,840.76 L1035.67,837.34 L1036.62,820.59 L1046.61,812.39 L1056.14,803.55 L1060.3,801.05 L1065.26,799.25 L1067.37,797.77 L1069.42,795.62 L1071.64,791.2 L1067.69,791.34 L1065.26,792 L1060.97,792.21 L1064.88,764.38 L1068.02,759.79 L1078.74,755.33 L1079.69,755.43 L1080.45,757.64 L1081.27,758.05 L1081.54,761.2 L1081.23,763.47 L1081.76,764.38 L1083.13,765.07 L1083.76,765.86 L1086.84,766.94 L1086.49,768.04 L1087.53,770.68 L1088.99,770.68 L1090.79,771.87 L1091.57,771.24 L1093.6,771.04 L1095.06,767.92 L1095.35,764.99 L1098.57,761.26 L1102.12,759.75 L1105,756.3 L1104.53,755.73 L1104.08,754.09 L1106.91,751.84 L1110.31,750.82 L1121.43,758.17 L1125.13,760.95 L1124.03,762.88 Z', 'held', '["arc"]', 'The fictional handover team at Bokjeong Station, where the boundaries of several districts meet, tries to keep outside supplies separate from Seoul''s internal stock.', '복정역 객체와 여러 구역의 경계가 만나는 지역의 창작 인계조는 외부 물자를 서울 내부 재고와 구분하려 한다.', 'Residents of Wirye-dong discuss the cost of the next choice: check the point of departure and the receiving area together.', '위례동 주민들은 다음 선택의 비용을 협의한다: 출발지와 수령 지역을 함께 확인한다.', 2, 2605974.371555775, 5158.876521097155);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171065000', 402, 'Jamsil-bondong', '잠실본동', 'Songpa-gu', '송파구', 'M918.69,683.59 L919.47,687.28 L920.54,690.02 L921.72,691.94 L923.39,693.8 L925.44,695.3 L927.56,696.35 L933.39,697.68 L912.93,727.35 L889.62,720.27 L883.02,716.9 L901.13,700.42 L897.92,681.9 L921.89,682.56 L918.69,683.59 Z', 'held', '["arc"]', 'The fictional merchants of Saemaeul Market share scales and packing tools and try to split the cost of breakdowns.', '새마을시장의 창작 상인들은 저울과 포장 도구를 공동으로 쓰며 고장 비용을 나누려 한다.', 'Residents of Jamsilbon-dong discuss the cost of the next choice: jointly check the condition before and after use.', '잠실본동 주민들은 다음 선택의 비용을 협의한다: 사용 전후 상태를 공동 확인한다.', 2, 1139330.3351780504, 7059.146721256321);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171067000', 403, 'Jamsil 2-dong', '잠실2동', 'Songpa-gu', '송파구', 'M921.89,682.56 L897.92,681.9 L884.46,684.35 L870.59,688.5 L869.62,687.48 L869.42,680.2 L866.04,652.56 L864.16,649.14 L865.56,634.2 L882.43,639.21 L895.97,639.76 L915.21,636.8 L927.36,633 L927.31,641.27 L938.7,681.93 L927.86,683.36 L921.89,682.56 Z', 'held', '["arc"]', 'The fictional ration team in the Jamsin Middle School yard tries to reduce crowded waiting by reserving the supplies each household needs.', '잠신중학교 마당의 창작 배급조는 가구별로 필요한 물자를 예약해 한꺼번에 몰리는 대기를 줄이려 한다.', 'Residents of Jamsil 2-dong discuss the cost of the next choice: split handover times by household.', '잠실2동 주민들은 다음 선택의 비용을 협의한다: 인계 시각을 가구별로 나눈다.', 0, 2875070.7275941866, 3597.0941169346247);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171068000', 404, 'Jamsil 3-dong', '잠실3동', 'Songpa-gu', '송파구', 'M968.58,695.97 L963.37,699 L959.63,700.79 L955.57,701.64 L953.31,701.57 L927.56,696.35 L924.21,694.5 L922.54,692.93 L921.1,691.02 L919.72,688.08 L918.69,683.59 L921.89,682.56 L927.86,683.36 L938.7,681.93 L927.31,641.27 L927.36,633 L932.87,631.19 L943.59,649.58 L963.71,682.8 L971.56,693.46 L968.58,695.97 Z', 'held', '["arc"]', 'Jamsil 3-dong looks out on the cold Han River and has no station of its own. The carrier team splits stored food and parts into small bundles kept in many separate rooms, so one theft or one failure does not take everything. Shutters stay down at night, and the team asks families to stay inside.', '잠실3동은 차가운 한강을 바라보며 자체 역이 없다. 운반조는 비축한 식량과 부품을 작은 묶음으로 나누어 여러 방에 흩어 두어 한 번의 도난이나 사고로 전부 잃지 않게 한다. 밤에는 덧문을 내리고 가족들에게 밖에 나가지 말라고 당부한다.', 'On opening day, Jamsil 3-dong residents re-bundle the essential food into small lots and record which room holds each one.', '개막일 잠실3동 주민들은 필수 식량을 작은 묶음으로 다시 나누고 어느 방에 무엇을 두었는지 적는다.', 0, 1513265.3513109174, 6619.2621084746925);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171069000', 405, 'Jamsil 4-dong', '잠실4동', 'Songpa-gu', '송파구', 'M996.72,661.27 L979.18,669.14 L968.86,645.72 L954.9,625.68 L957.32,624.27 L972.69,637.77 L977.9,638.94 L1007.27,638.84 L996.72,661.27 Z', 'held', '["arc"]', 'The fictional inspection team around Seongnaecheon Stream tries to notify residents of drainage and walkway conditions with the same signage.', '성내천 주변 창작 점검조는 물 빠짐과 보행 상태를 주민에게 같은 표지로 알리려 한다.', 'Residents of Jamsil 4-dong discuss the cost of the next choice: post the inspected drainage and walkway information separately.', '잠실4동 주민들은 다음 선택의 비용을 협의한다: 점검한 배수·보행 정보를 분리 게시한다.', 1, 839566.1465267467, 11786.444749990585);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171071000', 406, 'Jamsil 6-dong', '잠실6동', 'Songpa-gu', '송파구', 'M983.26,681.9 L971.56,693.46 L963.71,682.8 L943.59,649.58 L932.87,631.19 L938.08,628.39 L954.9,625.68 L968.86,645.72 L979.18,669.14 L983.26,681.9 Z', 'held', '["arc"]', 'Jangmi 1st Apartments in Jamsil 6-dong is a tall complex with one Arc station nearby. Households on the cold upper floors keep fuel and food in common, and the resident representative divides them among the complex''s families and nearby elders. The Eastern Rifle Guard watches the entrance, and everyone is reminded that a lit upper window can draw outside machines.', '잠실6동의 장미1차아파트는 근처에 아크 역이 한 곳 있는 높은 단지다. 추운 위층 가구들은 연료와 식량을 함께 모아 두고, 주민 대표가 단지 안 가족과 주변 노인에게 나눈다. 동방사가 출입구를 지키며, 불이 켜진 높은 창이 바깥 기계를 끌 수 있다는 주의를 모두가 듣는다.', 'On opening day, the representative sets aside separate amounts of fuel for the complex''s families and for the nearby elders and writes them on the entrance board.', '개막일 주민 대표는 단지 가족용 연료와 주변 노인용 연료를 따로 떼어 출입구 게시판에 적는다.', 1, 1397406.1707420482, 3456.189117467072);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1171072000', 407, 'Jamsil 7-dong', '잠실7동', 'Songpa-gu', '송파구', 'M883.02,716.9 L877.39,711.88 L873.39,706.36 L872.32,701.3 L870.59,688.5 L884.46,684.35 L897.92,681.9 L901.13,700.42 L883.02,716.9 Z', 'held', '["arc"]', 'The fictional assembly team around Jonghapundongjang Station checks that different guides in the wide open space do not hand over the same people twice.', '종합운동장역 주변 창작 집결조는 넓은 장소에서 서로 다른 안내자가 같은 인원을 중복 인계하지 않도록 확인한다.', 'Residents of Jamsil 7-dong discuss the cost of the next choice: appoint a handover manager for each zone.', '잠실7동 주민들은 다음 선택의 비용을 협의한다: 구획별 인계 책임자를 정한다.', 2, 680053.6344608059, 4077.4725102359744);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174051500', 408, 'Gangil-dong', '강일동', 'Gangdong-gu', '강동구', 'M1178.01,518.75 L1170.3,519.83 L1165.57,519.35 L1162.79,501.07 L1171.01,496.39 L1153.79,470.4 L1154.09,470.1 L1148.21,459.55 L1139.43,450.51 L1151.91,441.56 L1157.48,441.49 L1167.09,439.82 L1172.92,439.26 L1175.95,437.57 L1181.48,435.22 L1183.57,434.78 L1181.56,439.74 L1177.36,443.6 L1176.92,447.53 L1178.2,456.32 L1179.11,458.89 L1183.9,468.5 L1187.57,476.87 L1188.52,482.58 L1188.93,489.77 L1189.37,491.62 L1193.22,501.02 L1195.24,505.03 L1195.65,506.43 L1195.67,511.93 L1195.36,513.93 L1178.01,518.75 Z', 'held', '["arc"]', 'The fictional assembly team at Gangbit Elementary School tries to add newly arrived households to a temporary ration list and run the duplicate check afterward.', '강빛초등학교의 창작 집결조는 새로 온 가구를 임시 배급 명단에 올리되 중복 확인을 뒤에 진행하려 한다.', 'Residents of Gangil-dong discuss the cost of the next choice: separate temporary registration from after-the-fact verification.', '강일동 주민들은 다음 선택의 비용을 협의한다: 임시 등록과 사후 확인을 분리한다.', 0, 2186049.5868088487, 4689.692339031301);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174052500', 409, 'Sangilje 1-dong', '상일제1동', 'Gangdong-gu', '강동구', 'M1172.55,561.85 L1144.28,564.13 L1141.65,563.56 L1139.71,560.36 L1131.61,561.67 L1129.67,561.62 L1120.88,559.15 L1122.83,526.21 L1147.56,521.87 L1165.57,519.35 L1169.95,547.71 L1171.61,556.85 L1172.99,562.26 L1172.55,561.85 Z', 'held', '["arc"]', 'The fictional transport team around Sangil-dong Station tries to separate the handover of residential belongings and workshop parts at the same entrance.', '상일동역 주변 창작 운반조는 주거지의 짐과 작업장 부품 인계를 같은 출입구에서 나누려 한다.', 'Residents of Sangil 1-dong discuss the cost of the next choice: reserve household ration handovers first.', '상일제1동 주민들은 다음 선택의 비용을 협의한다: 가구 배급 인계를 먼저 예약한다.', 1, 1779823.2752693824, 6564.752895610702);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174052600', 410, 'Sangilje 2-dong', '상일제2동', 'Gangdong-gu', '강동구', 'M1170.3,519.83 L1178.01,518.75 L1195.36,513.93 L1194.51,518.4 L1193.89,535.55 L1197.93,558.2 L1200,560.86 L1192.43,560.63 L1190.21,558.6 L1187.1,557.88 L1183.04,559.41 L1177.18,562.98 L1173.73,562.96 L1172.99,562.26 L1171.61,556.85 L1169.95,547.71 L1165.57,519.35 L1170.3,519.83 Z', 'held', '["arc"]', 'The fictional handover team, whose Gangil Station is assigned to the Sangil 2-dong profile, does not treat the station name and the administrative dong name as the same thing.', '강일역이 상일제2동 프로필에 배정된 창작 인계조는 역 이름과 행정동 이름을 같은 것으로 보지 않는다.', 'Residents of Sangil 2-dong discuss the cost of the next choice: record the station handover point and the ration household area together.', '상일제2동 주민들은 다음 선택의 비용을 협의한다: 역 인계처와 배급 가구 지역을 함께 적는다.', 1, 1084951.023816829, 3627.2605063363744);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174053000', 411, 'Myeongil 1-dong', '명일1동', 'Gangdong-gu', '강동구', 'M1102.98,541.09 L1099.75,560.67 L1096.97,559.9 L1091.34,563.96 L1091.69,565.74 L1083.02,563.16 L1083.63,562.78 L1084.69,559.09 L1086.59,542.59 L1077.19,542.06 L1076.35,541.24 L1076.18,540.63 L1084.46,528.82 L1088.14,528.26 L1104.58,528.6 L1102.98,541.09 Z', 'held', '["arc"]', 'The fictional care team at Gomyeong Elementary School looks after children in the classroom while guardians go out to carry rations. The fictional care team of Myeongil 1-dong checks with guardians the meals each household needs and the usable ingredients.', '고명초등학교의 창작 돌봄조는 보호자가 배급 운반을 나갈 때 교실에서 아이를 맡는다. 명일1동의 창작 돌봄조는 가구별 필요한 식사와 사용 가능한 식재료를 보호자와 함께 확인한다.', 'Residents of Myeongil 1-dong discuss the cost of the next choice: set up a rotating shift system for guardians.', '명일1동 주민들은 다음 선택의 비용을 협의한다: 보호자 순환 교대를 둔다.', 1, 620722.1541411908, 11972.98976751122);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174054000', 412, 'Myeongil 2-dong', '명일2동', 'Gangdong-gu', '강동구', 'M1133.61,575.85 L1131.74,572.98 L1130.09,571.45 L1123.38,569.4 L1114.2,569.82 L1100.15,562.94 L1099.75,560.67 L1102.98,541.09 L1104.58,528.6 L1122.83,526.21 L1120.88,559.15 L1129.67,561.62 L1131.61,561.67 L1139.71,560.36 L1141.65,563.56 L1133.61,575.85 Z', 'held', '["arc"]', 'The fictional repair team around Godeok Station inspects the condition of shared tools when they are returned, so that responsibility for damage is not passed on to the next user.', '고덕역 주변 창작 수리조는 공용 도구를 반납할 때 상태를 검사해 다음 사용자에게 손상 책임을 넘기지 않으려 한다.', 'Residents of Myeongil 2-dong discuss the cost of the next choice: carry out inspections when tools are returned.', '명일2동 주민들은 다음 선택의 비용을 협의한다: 공구 반납 검사를 실시한다.', 1, 936772.0678819815, 5394.268438666366);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174055000', 413, 'Godeok 1-dong', '고덕1동', 'Gangdong-gu', '강동구', 'M1104.58,528.6 L1088.14,528.26 L1088.54,522.92 L1087.05,514.3 L1092.43,507.88 L1096.2,504.43 L1090.46,489.73 L1091.01,479.69 L1101.99,478.94 L1112.52,471.12 L1113.67,482.44 L1117.68,480.08 L1119.38,479.97 L1121.16,480.84 L1122.37,483.08 L1123.93,498.91 L1122.83,526.21 L1104.58,528.6 Z', 'held', '["arc"]', 'The fictional training team at Baejae Middle School tries to teach everyday repair skills, but on-site orders eat into the teaching time.', '배재중학교의 창작 실습조는 생활 수리 기술을 가르치려 하지만 현장 주문이 교육 시간을 잠식한다.', 'Residents of Godeok 1-dong discuss the cost of the next choice: reserve apprenticeship practice time.', '고덕1동 주민들은 다음 선택의 비용을 협의한다: 도제 실습 시간을 예약한다.', 0, 1524709.296610117, 4633.670179428695);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174056000', 414, 'Godeok 2-dong', '고덕2동', 'Gangdong-gu', '강동구', 'M1152.44,521.16 L1122.83,526.21 L1123.93,498.91 L1122.37,483.08 L1121.16,480.84 L1119.38,479.97 L1117.68,480.08 L1113.67,482.44 L1112.52,471.12 L1139.43,450.51 L1148.21,459.55 L1154.09,470.1 L1153.79,470.4 L1171.01,496.39 L1162.79,501.07 L1165.57,519.35 L1152.44,521.16 Z', 'held', '["arc"]', 'Godeok 2-dong borders the cold Han River and has no station of its own. The inspection team walks the riverside path in daylight, checks that shutters are down on the river side, and keeps stored goods away from the walkway. Residents fear that someone will take a person from the lonely riverbank.', '고덕2동은 차가운 한강과 맞닿아 있고 자체 역이 없다. 점검조는 낮에 강변길을 걸으며 강 쪽 덧문이 내려가 있는지 보고, 보관한 물자를 통행로에서 떨어뜨려 둔다. 주민들은 인적 드문 강변에서 누가 사람을 끌고 갈까 봐 걱정한다.', 'On opening day, Godeok 2-dong residents first decide which inner rooms will shelter the essential food and parts.', '개막일 고덕2동 주민들은 필수 식량과 부품을 둘 안쪽 대피실부터 정한다.', 0, 2506737.7742281365, 3143.926772486876);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174057000', 415, 'Amsa 1-dong', '암사1동', 'Gangdong-gu', '강동구', 'M1084.46,528.82 L1076.18,540.63 L1076.35,541.24 L1077.19,542.06 L1078.72,542.27 L1069.37,544.42 L1067.55,545.66 L1061.29,553.19 L1059.68,555.69 L1039.92,545 L1044.37,528.12 L1088.14,528.26 L1084.46,528.82 Z', 'held', '["arc"]', 'Amsa Hansol Apartments in Amsa 1-dong is a cold complex with no station of its own. The resident representative draws each household''s fuel and food, and any request for outside help, from one common stock, and keeps the lights off after dark. Deeper floors are warmer and held by higher households.', '암사1동의 암사한솔아파트는 자체 역이 없는 추운 단지다. 주민 대표는 가구별 연료·식량과 외부 도움 요청분을 하나의 공동 재고에서 배정하고, 해가 지면 불을 끄게 한다. 아래층일수록 따뜻하고 높은 신분의 가구가 산다.', 'On opening day, the representative reserves each household''s essential fuel and food first, before any outside request.', '개막일 주민 대표는 외부 요청보다 먼저 가구마다 꼭 필요한 연료와 식량을 예약해 둔다.', 0, 729664.5585571819, 13326.123471348497);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174058000', 416, 'Amsa 2-dong', '암사2동', 'Gangdong-gu', '강동구', 'M1039.92,545 L1037.23,552.82 L1026.26,549.6 L1026.98,547.1 L996.29,546.84 L1000.49,533.1 L1000.59,514.14 L999.43,508.18 L1005.15,509.65 L1008.59,509.05 L1016.29,499.59 L1023.16,494.8 L1024.69,493.87 L1050.79,482.46 L1057.82,478.92 L1056.67,491.53 L1053.45,503.82 L1049.9,510.17 L1048.47,514.21 L1044.37,528.12 L1039.92,545 Z', 'held', '["arc"]', 'Amsa 2-dong has one Arc station at Amsa Station, where guards count arrivals and goods. The distribution team hands out only what is physically counted at the station, not what was promised. Machine-body owners queue for repair slots, and the station''s lights are kept low because of outside machines.', '암사2동에는 암사역에 아크 역이 한 곳 있어 경비가 도착한 사람과 짐을 센다. 배급조는 약속된 양이 아니라 역에서 실제로 센 양만 가구에 나눠 준다. 기계 몸 주민은 수리 차례를 기다려 줄을 서며, 바깥 기계 때문에 역의 불은 낮게 둔다.', 'On opening day, Amsa 2-dong residents share out food only by the amount actually counted at the station that morning.', '개막일 암사2동 주민들은 그날 아침 역에서 실제로 센 양만큼만 식량을 나눈다.', 1, 2440732.3317079623, 1784.3415041551941);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174059000', 417, 'Amsa 3-dong', '암사3동', 'Gangdong-gu', '강동구', 'M1088.14,528.26 L1044.37,528.12 L1049.72,510.62 L1053.45,503.82 L1056.67,491.53 L1057.82,478.92 L1091.01,479.69 L1090.46,489.73 L1096.2,504.43 L1092.43,507.88 L1087.05,514.3 L1088.54,522.92 L1088.14,528.26 Z', 'held', '["arc"]', 'The fictional guidance team at Amsayeoksagongwon Station hands over so that the return checks for residents who have set out are not broken even when shifts change.', '암사역사공원역의 창작 안내조는 교대가 바뀌어도 출발한 주민의 귀환 확인이 끊기지 않도록 인계한다.', 'Residents of Amsa 3-dong discuss the cost of the next choice: hand over the departure and return lists together.', '암사3동 주민들은 다음 선택의 비용을 협의한다: 출발·귀환 명단을 함께 인계한다.', 1, 1796162.1912960545, 2811.828477669779);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174060000', 418, 'Cheonho 1-dong', '천호1동', 'Gangdong-gu', '강동구', 'M1079.99,573.2 L1069.64,570.09 L1056.83,572.59 L1049.78,572.67 L1061.29,553.19 L1067.55,545.66 L1069.37,544.42 L1078.72,542.27 L1086.59,542.59 L1084.69,559.09 L1083.63,562.78 L1083.02,563.16 L1079.99,573.2 Z', 'held', '["arc"]', 'The fictional guidance team around Gubeundari Station tries to share the space between cargo waiting and residents who need to rest.', '굽은다리역 주변 창작 안내조는 화물 대기와 쉬어 가야 하는 주민의 자리를 나눠 쓰려 한다.', 'Residents of Cheonho 1-dong discuss the cost of the next choice: secure waiting seats for care.', '천호1동 주민들은 다음 선택의 비용을 협의한다: 돌봄 대기석을 확보한다.', 1, 684873.046630101, 10399.445612650521);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174061000', 419, 'Cheonho 2-dong', '천호2동', 'Gangdong-gu', '강동구', 'M1059.68,555.69 L1047.99,575.56 L1045.82,577.81 L1042.67,579.22 L1036.18,589.65 L1029.46,587.59 L1022.41,584.21 L1016.42,579.48 L1013.52,577.79 L987.95,568.54 L993.74,557.62 L995.2,553.9 L996.29,546.84 L1026.98,547.1 L1026.26,549.6 L1037.23,552.82 L1039.92,545 L1059.68,555.69 Z', 'held', '["arc"]', 'The fictional liaison team at Cheonho Station tries to update schedule changes across several zones in the same shift. The fictional liaison team of Cheonho 2-dong tries to reduce duplicate searches by linking identical missing-person reports received at different handover points.', '천호역의 창작 연락조는 여러 구획의 일정 변경을 같은 교대에 갱신하려 한다. 천호2동의 창작 연락조는 서로 다른 인계처에 접수된 같은 분실 신고를 연결해 중복 수색을 줄이려 한다.', 'Residents of Cheonho 2-dong discuss the cost of the next choice: separate confirmed schedules from unconfirmed messages.', '천호2동 주민들은 다음 선택의 비용을 협의한다: 확인된 일정과 확인되지 않은 전갈을 나눈다.', 1, 1827169.3503070648, 5916.200377476419);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174062000', 420, 'Cheonho 3-dong', '천호3동', 'Gangdong-gu', '강동구', 'M1074.24,577.51 L1069.16,577.17 L1067.66,577.55 L1066.78,578.37 L1064.55,583.17 L1058.97,597.62 L1036.18,589.65 L1042.67,579.22 L1045.82,577.81 L1047.99,575.56 L1049.78,572.67 L1056.83,572.59 L1069.64,570.09 L1079.99,573.2 L1074.24,577.51 Z', 'held', '["arc"]', 'The fictional medical team in the Gangdong Mizu Women''s Hospital building tries to secure seats for guardians to wait in while receiving general goods at a different time.', '강동미즈여성병원 건물의 창작 의무조는 보호자가 기다릴 자리를 확보하면서 일반 물품 수령을 다른 시각에 받으려 한다.', 'Residents of Cheonho 3-dong discuss the cost of the next choice: separate goods collection from guardian waiting.', '천호3동 주민들은 다음 선택의 비용을 협의한다: 물품 수령과 보호자 대기를 분리한다.', 0, 538427.8324143708, 15472.825694472109);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174064000', 421, 'Seongnae 1-dong', '성내1동', 'Gangdong-gu', '강동구', 'M1042.63,639.6 L1015.23,624.11 L1019.74,612.42 L1021.32,605.98 L1033.71,610.5 L1035.06,607.83 L1036.32,606.39 L1038.5,609.99 L1037.9,611.96 L1051.55,616.78 L1042.63,639.6 Z', 'held', '["arc"]', 'The fictional clerk around Gangdong-gu Office Station tries to accept ration handovers and service negotiations separately.', '강동구청역 주변 창작 서기는 배급 인계와 복무 협의를 별도 접수하려 한다.', 'Residents of Seongnae 1-dong discuss the cost of the next choice: separate handover signatures from service negotiations.', '성내1동 주민들은 다음 선택의 비용을 협의한다: 인계 서명과 복무 협의를 분리한다.', 1, 661069.3815726897, 8535.715247582588);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174065000', 422, 'Seongnae 2-dong', '성내2동', 'Gangdong-gu', '강동구', 'M1046.24,593.29 L1054.85,595.99 L1058.97,597.62 L1051.55,616.78 L1037.9,611.96 L1038.5,609.99 L1036.32,606.39 L1035.06,607.83 L1033.71,610.5 L1021.32,605.98 L1026.99,586.49 L1029.46,587.59 L1036.18,589.65 L1046.24,593.29 Z', 'held', '["arc"]', 'The fictional technical team in the building marked as the Korea Information Technology Promotion Agency tries to divide the remaining equipment between communications restoration and resident education.', '한국정보기술진흥원으로 표시된 건물의 창작 기술조는 남은 장비를 연락 복구와 주민 교육에 나누어 쓰려 한다.', 'Residents of Seongnae 2-dong discuss the cost of the next choice: set aside equipment time for basic education.', '성내2동 주민들은 다음 선택의 비용을 협의한다: 기초 교육용 장비 시간을 남긴다.', 1, 626084.1054710638, 11388.885195600213);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174066000', 423, 'Seongnae 3-dong', '성내3동', 'Gangdong-gu', '강동구', 'M1070.95,603.01 L1057.4,647.76 L1042.63,639.6 L1058.69,598.34 L1070.95,603.01 Z', 'held', '["arc"]', 'The fictional cooking team at Dunchon Station Traditional Market tries to organize the open-flame zone in an indoor space full of stalls and packaging materials.', '둔촌역 전통시장의 창작 취사조는 좌판과 포장재가 많은 실내에서 화기 구획을 정리하려 한다.', 'Residents of Seongnae 3-dong discuss the cost of the next choice: consolidate open-flame work into one zone.', '성내3동 주민들은 다음 선택의 비용을 협의한다: 화기 작업을 한 구획으로 모은다.', 1, 641575.0248053037, 10080.972216714215);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174068500', 424, 'Gil-dong', '길동', 'Gangdong-gu', '강동구', 'M1100.15,562.94 L1114.2,569.82 L1123.38,569.4 L1130.09,571.45 L1131.74,572.98 L1133.61,575.85 L1088.8,599.5 L1083.79,602.06 L1080.07,603.55 L1076.43,603.92 L1070.95,603.01 L1058.69,598.34 L1064.55,583.17 L1066.78,578.37 L1067.66,577.55 L1069.16,577.17 L1074.24,577.51 L1079.99,573.2 L1083.02,563.16 L1091.69,565.74 L1091.34,563.96 L1096.97,559.9 L1099.75,560.67 L1100.15,562.94 Z', 'held', '["arc"]', 'The fictional medical team in the Gangdong Seongsim Hospital building separates supplies for emergency preparedness from household support allotments in the same ledger.', '강동성심병원 건물의 창작 의무조는 응급 준비용 물자와 가구 지원분을 같은 장부에서 분리한다.', 'Residents of Gil-dong discuss the cost of the next choice: set aside the minimum emergency stock first.', '길동 주민들은 다음 선택의 비용을 협의한다: 응급 최소 재고를 먼저 남긴다.', 1, 1599869.6313770749, 8802.529733549763);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174069000', 425, 'Dunchon 1-dong', '둔촌1동', 'Gangdong-gu', '강동구', 'M1092.51,642.36 L1088.4,655.53 L1089.16,664.47 L1088.03,664.37 L1084,662.61 L1057.4,647.76 L1065.32,621.57 L1088.49,629.9 L1092.42,639.11 L1092.51,642.36 Z', 'held', '["arc"]', 'The fictional encampment team at Wirye Elementary School tries to keep the emergency passages clear by separating sleeping spaces from household belongings.', '위례초등학교의 창작 숙영조는 잠자리와 생활 짐을 분리해 비상 통로를 비워 두려 한다.', 'Residents of Dunchon 1-dong discuss the cost of the next choice: move the storage of household belongings to a separate zone.', '둔촌1동 주민들은 다음 선택의 비용을 협의한다: 생활 짐 보관을 별도 구획으로 옮긴다.', 1, 895456.9853427708, 11067.198271066572);
INSERT INTO map_region (id, sort, name, name_ko, district, district_ko, path, status, polities, summary, summary_ko, opening_state, opening_state_ko, station_count, area_m2, density_2126) VALUES ('region:1174070000', 426, 'Dunchon 2-dong', '둔촌2동', 'Gangdong-gu', '강동구', 'M1113.88,603.14 L1113.72,616.34 L1112.99,619.93 L1112.55,620.79 L1110.59,623.51 L1102.39,632.3 L1100.63,638.4 L1099.07,642.56 L1097.13,645.65 L1096.15,646.01 L1091.5,646.27 L1092.51,642.36 L1092.42,639.11 L1088.49,629.9 L1065.32,621.57 L1070.95,603.01 L1073.06,603.51 L1077.71,603.86 L1080.07,603.55 L1083.79,602.06 L1133.61,575.85 L1128.65,581.05 L1125.44,585.04 L1123.8,587.44 L1123.77,588.98 L1123.04,590.29 L1116.77,599.8 L1114.74,602.51 L1113.88,603.14 Z', 'held', '["arc"]', 'The fictional care team around Jungang Bohun Hospital Station divides the time so that handovers of slow walkers and stretchers are not crowded out by cargo unloading.', '중앙보훈병원역 주변 창작 돌봄조는 느린 보행자와 들것 인계가 화물 하역에 밀리지 않도록 시간을 나눈다.', 'Residents of Dunchon 2-dong discuss the cost of the next choice: clear the care handover section first.', '둔촌2동 주민들은 다음 선택의 비용을 협의한다: 돌봄 인계 구간을 먼저 비운다.', 1, 1592761.7148968563, 4732.534646896715);
