INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('cheong-wa-dae', 0, 'Cheongwadae', '청와대', 'region:1111051500', 'government', 'Core Fortress · Government Center', '핵심 요새·정부 중심지', 'The office and residence of the President and the center of records, rations, and ratification; the core fortress of the Government. The Government Complex Seoul Main Building remains the forward administrative and defense post.', '대통령의 집무·거처와 기록·배급·인준의 중심지이며 정부의 핵심 요새다. 정부서울청사 본관은 전방 행정·방어 거점으로 남는다', 606.26, 411.13, 'confirmed');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('government-complex-seoul', 1, 'Government Complex Seoul Main Building', '정부서울청사 본관', 'region:1111053000', 'government', 'Forward Administrative and Defense Post', '전방 행정·방어 거점', 'Handles security and passage for Gwanghwamun, Jongno 3-ga, and Euljiro-ipgu.', '광화문·종로3가·을지로입구 경비와 통행을 맡는다', 603.02, 453.53, 'confirmed');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('fki-hall', 2, 'Yeouido FKI Building', '여의도 전경련회관', 'region:1156054000', 'free-city', 'Meeting and Investment Ledger Support Post', '회의·출자 장부 보조 거점', 'Assists with the food and fuel stock ledgers and shift records of the Yeouido market quarters beside the National Assembly Building.', '국회의사당 곁에서 여의도 일대 상가의 식량·연료 재고 장부와 교대 기록을 보조한다', 445.88, 641.46, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('jogyesa', 3, 'Jogyesa', '조계사', 'region:1111061500', 'government', 'Ritual and Ratification Center', '의례·인준 중심지', 'Handles the rites and ratification of the Government.', '정부의 의례와 인준을 맡는다', 622.75, 456.36, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('myeongdong-sanctuary', 4, 'Arc sanctuary', 'Arc 성소', 'region:1114055000', 'government', 'Ceremonial and Administrative Center', '예식·행정 중심지', 'Handles the ceremonies and administration of the Arc.', 'Arc의 예식과 행정을 맡는다', 637.56, 495.98, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('lotte-world-tower', 5, 'Lotte World Tower', '롯데월드타워', 'region:1171071000', 'arc', 'Leader''s Residence · Above- and Below-Ground Core Fortress', '수장 거주·지상·지하 핵심 요새', 'The core fortress of the Government, where Nam Yun-gyeong (K373), Stationmaster of Myeongdong Station, resides. It uses the tower and the mall basement, with passage via the connecting passage to Jamsil Station. The ceremonial and administrative functions of the capital Myeongdong Station and Arc sanctuary are maintained.', '명동역 역장 남윤경(K373)이 거주하는 정부의 핵심 요새다. 타워와 몰 지하를 사용하며 잠실역 연결 통로로 통행한다. 수도 명동역과 Arc 성소의 예식·행정 기능은 유지한다', 967.75, 679.75, 'confirmed');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('n-seoul-tower', 6, 'N Seoul Tower', 'N서울타워', 'region:1117052000', 'government', 'Observation and Manual Signal Relay Post', '관측·수동 신호 중계 거점', 'Observes all of Seoul and relays manual signals. The Government uses Namsan Tower as its base, and the organization is led by O Hae-rin, the current avatar of the Government AI.', '서울 전역을 관측하고 수동 신호를 중계한다. 정부는 남산타워를 거점으로 사용하며 정부 AI의 현재 아바타 오해린이 조직을 이끈다', 640.59, 538.8, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('national-assembly', 7, 'National Assembly Building', '국회의사당', 'region:1156054000', 'free-city', 'Leader''s Residence · Top-Priority Core Fortress', '수장 거주·최우선 핵심 요새', 'The top-priority core fortress of the Free City, where Guild Master Choe Ji-u (K219) resides. The old plenary chamber is used as the meeting hall for representatives of the Investment Guild.', '조합장 최지우(K219)가 거주하는 자유도시의 최우선 핵심 요새다. 옛 본회의장은 출자 조합 대표 회의장으로 쓴다', 427.63, 607.41, 'confirmed');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('ddp', 8, 'Dongdaemun Design Plaza', '동대문디자인플라자', 'region:1114059000', 'government', 'Above- and Below-Ground Passage and Goods Inspection Post', '지상·지하 통행·물자 검사 거점', 'Inspects passage and goods both above and below ground.', '지상과 지하의 통행 및 물자를 검사한다', 702.79, 482.26, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('city-hall', 9, 'Seoul City Hall', '서울시청', 'region:1114055000', 'government', 'Downtown Public Administration Post', '도심 공공업무 거점', 'The government uses it as its public administration counter in the city center.', '정부가 도심의 공공업무 창구로 사용한다', 612.61, 482.78, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('seoul-station', 10, 'Old Seoul Station Building', '서울역 옛 역사', 'region:1114054000', 'government', 'Railway Shift and Records Post', '철도 교대·기록 거점', 'Checks railway shifts and records at Seoul Station Plaza.', '서울역 광장의 철도 교대와 기록을 확인한다', 592.69, 521.54, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('war-memorial', 11, 'War Memorial of Korea', '전쟁기념관', 'region:1117053000', 'government', 'Yongsan Records and Assembly Post', '용산 기록·집회 거점', 'The Government uses it for Yongsan record reconciliation and assemblies.', '정부가 용산의 기록 대조와 집회에 사용한다', 608.76, 593.69, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('jamsil-stadium', 12, 'Jamsil Sports Complex', '잠실종합운동장', 'region:1171067000', 'arc', 'Jamsil Assembly Post', '잠실 집회 거점', 'The Arc holds large assemblies in Jamsil here.', 'Arc가 잠실의 대규모 집회를 연다', 884.79, 670.48, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('bldg63', 13, '63 Building', '63빌딩', 'region:1156054000', 'free-city', 'Yeouido Observation Post', '여의도 관측 거점', 'The Free City observes access along the riverside and downtown.', '자유도시가 강변과 도심의 접근을 관측한다', 502.26, 651.12, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('coex', 14, 'COEX', '코엑스', 'region:1168058000', 'arc', 'Samseong-dong Negotiation and Supply Exchange Post', '삼성동 교섭·물자 교환 거점', 'The Arc uses it for negotiations and supply exchanges in Samseong-dong.', 'Arc이 삼성동의 교섭과 물자 교환에 사용한다', 842.84, 681.64, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('gwanghwamun', 15, 'Gwanghwamun', '광화문', 'region:1111051500', 'government', 'Cheongwadae Approach Watch', '청와대 접근 경계', 'Watches the downtown approach routes leading to Cheongwadae.', '청와대로 향하는 도심 접근로를 감시한다', 608.19, 449.89, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('heunginjimun', 16, 'Heunginjimun', '흥인지문', 'region:1111063000', 'government', 'Eastern Downtown Observation Post', '동부 도심 관측 거점', 'The government observes access to eastern downtown.', '정부가 동부 도심 접근을 관측한다', 702.03, 467.7, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('sungnyemun', 17, 'Sungnyemun', '숭례문', 'region:1114054000', 'government', 'Southern Downtown Observation Post', '남부 도심 관측 거점', 'The government observes access to southern downtown.', '정부가 남부 도심 접근을 관측한다', 603.69, 507.2, 'unknown');
INSERT INTO map_landmark (id, sort, name, name_ko, region_id, holder_id, role, role_ko, detail, detail_ko, x, y, fortification) VALUES ('bosingak', 18, 'Bosingak', '보신각', 'region:1111061500', 'government', 'Downtown Manual Signal Post', '도심 수동 신호 거점', 'The government relays manual signals across the Jongno area.', '정부가 종로 일대에 수동 신호를 전한다', 627.53, 471.84, 'unknown');
